(window.GioKinhBooks=window.GioKinhBooks||{})["pham-vong"]={"id":"pham-vong","title":"Kinh Phạm Võng Bồ Tát Giới","by":"Việt dịch: HT Thích Trí Tịnh · Mười giới trọng và 48 giới khinh","src":"https://www.daotranglienhoa.com/wp-content/uploads/2024/08/kinh_pham_vong.pdf","srcName":"Đạo Tràng Liên Hoa","chapters":[{"t":"Nghi Thức Tụng Giới Bồ Tát Bài Tán Lư Hương","b":[["v",["Lò hương vừa ngún chiên đàn","Khói thơm ngào ngạt muôn ngàn cõi xa","Lòng con kính ngưỡng thiết tha","Ngửa mong chư Phật thương mà chứng"]],["v",["minh.","Nam mô Phạm Võng Giáo Chủ Lô Xá Na","Phật. (3 lần)"]]]},{"t":"Bài Kệ Khai Kinh","b":[["v",["Phật pháp rộng sâu rất nhiệm mầu","Trăm nghìn muôn kiếp khó tìm cầu","Con nay nghe thấy chuyên trì tụng","Nguyện hiểu Như Lai nghĩa nhiệm mầu."]],["p","Nam mô Bổn Sư Thích Ca Mâu Ni Phật."],["p","(3 lần) (Trên đây là bài Hương Tán và bài Kệ Khai Kinh. Có thể"],["p","tụng theo nguyên văn chữ Hán.)"],["v",["Chúng thọ Bồ Tát giới lắng nghe!","Quy mạng Lô Xá Na,","Mười phương Kim Cương Phật,","Đảnh lễ đức Di Lặc,","Sẽ hạ sanh thành Phật.","Nay tụng ba tựu giới,","Bồ Tát đều cùng nghe.","Giới như đèn sáng lớn,","Soi sáng đêm tối tăm.","Giới như gươm báu sáng,","Chiếu rõ tất cả pháp.","Giới như Ma Ni châu,","Rưới của giúp người nghèo.","Thoát khổ mau thành Phật,","Chỉ giới này hơn cả.","Vì thế nên Bồ Tát,","Phải tinh tấn giữ gìn."]],["p","Chư Đại Đức! (Chư Đại chúng! Chư Phật tử!) Phần mùa xuân (mùa Hạ, mùa Đông)\u0001 bốn tháng làm một mùa. Nửa tháng đã qua (một tháng, tháng rưỡi, hai tháng, hai tháng rưỡi, ba tháng, ba tháng rưỡi, bốn tháng)\u0001 thiếu một đêm, thừa một đêm\u0001 còn ba tháng rưỡi (ba tháng, hai tháng rưỡi, hai tháng, một tháng rưỡi, một tháng, nửa tháng)\u0001"],["p","Già chết gần kề, Phật Pháp sắp diệt, chư Đại Đức (Đại chúng, Phật tử), vì muốn đắc đạo nên nhất tâm cần cầu tinh tấn."],["p","Chư Phật do nhất tâm cần cầu tinh tấn nên đặng chứng quả vô thượng chánh giác, huống là các pháp lành khác."],["p","Nhân lúc còn mạnh khỏe, các ngài phải gắng sức siêng tu pháp lành. Đâu nên chẳng gấp cầu đạo lại chần chờ đợi già yếu. Còn mong mỏi thú vui gì?"],["v",["Ngày nay đã qua,","Mạng sống giảm lần,","Như cá cạn nước,","Nào có vui chi!"]],["p","HỎI\u0001 Chúng nhóm chưa? (Vị tụng giới"],["v",["hỏi.)","ĐÁP\u0001 Chúng đã nhóm. (Vị tri sự đáp.)","HỎI\u0001 Hòa hiệp chăng?","ĐÁP\u0001 Hòa hiệp.","HỎI\u0001 Chúng nhóm họp để làm gì?","ĐÁP\u0001 Thuyết giới Bồ Tát.","HỎI\u0001 Người chưa thọ giới Bồ Tát và người"]],["v",["không thanh tịnh ra chưa?","ĐÁP\u0001 Trong đây không có người chưa thọ"]],["p","giới Bồ Tát và người không thanh tịnh. (Nếu có thì bảo ra, rồi đáp rằng: Người chưa thọ giới Bồ tát và không thanh tịnh đã ra.)"],["p","HỎI\u0001 Có bao nhiêu vị Bồ Tát khiếm diện"],["v",["thuyết dục và thanh tịnh?","ĐÁP\u0001 Trong đây không có Bồ Tát khiếm"]],["p","diện thuyết dục và thanh tịnh. (Nếu có thời ra thuyết dục. Nên ra thưa:"],["p","Chư Đại Đức lắng nghe cho. Tôi là Bồ Tát\u0001.. có lãnh giữ dục của Bồ Tát ... những việc làm đúng pháp của Tăng, Bồ Tát\u0001.. giữ dục và thanh tịnh.)"],["p","Chư Đại Đức! (Đại chúng, Phật tử) chắp tay chí tâm lắng nghe! Nay tôi sắp tụng lời tựa về pháp Đại thừa của chư Phật. Đại chúng lẳng lặng lắng nghe."],["p","Trong đây vị nào biết mình có tội phải sám hối. Sám hối thời được an vui. Không sám hối thì tội lỗi càng thêm nặng. Người không có lỗi thời yên lặng. Vì yên lặng nên biết đại chúng thanh tịnh."],["p","Chư Đại Đức! (Đại chúng, Phật tử) lắng nghe. Sau khi đức Phật diệt độ, trong thời mạt pháp, nên phải tôn kính Ba La Đề Mộc Xoa\u0001 Ba La Đề Mộc Xoa chính là giới pháp này. Trì giới này thời như đi đêm tối gặp đèn sáng, như người nghèo được của báu, như bệnh được lành, như người tù được thả, như kẻ đi xa được về nhà. Nên biết rằng giới pháp này là đức Thầy sáng suốt của đại chúng, không khác đức Phật còn ở đời."],["p","Nếu không có lòng sợ tội, thời tâm lành khó nảy nở. Cho nên trong kinh có lời dạy: Chớ xem thường những lỗi nhỏ mà cho là không hại, giọt nước dầu nhỏ mà lần đầy cả chum lớn. Lúc tạo tội chừng trong giây phút, mà phải cả nghìn muôn năm chịu khổ nơi địa ngục. Một phen bị đọa lạc mất thân người, thời muôn đời khó được lại."],["p","Sắc trẻ không dừng, dường như ngựa chạy. Mạng người vô thường, mau hơn nước dốc. Ngày nay dầu còn, khó bảo đảm được ngày mai. Đại chúng mỗi người nên nhất tâm cần cầu tinh tấn. Chớ biếng nhác trễ lười, phóng túng ngủ nghỉ. Ban đêm phải nhiếp tâm niệm Phật tham thiền, chớ để thời gian luống qua vô ích, mà sau này phải ăn năn."],["p","Đại Chúng! Mỗi người nên nhất tâm cung kính y theo giới này như pháp tu hành, cần nên học tập."],["p","Chư Đại Đức! (Đại chúng, Phật tử) Nay là ngày thứ mười lăm (mười bốn) có trăng (không trăng), làm phép Bố Tát"],["p","tụng Bồ Tát giới. Đại chúng nên nhất tâm nghe kỹ."],["p","Ai có tội thời phát lồ. Người không tội thời im lặng. Vì im lặng nên biết đại chúng thanh tịnh, có thể tụng giới Bồ Tát."],["p","Tôi đã tụng lời tựa của giới Bồ Tát rồi."],["p","Nay xin hỏi trong đại chúng đây được thanh tịnh không? (Hỏi 3 lần)"],["p","Thưa Đại Chúng! Trong đây thanh tịnh, vì yên lặng. Việc này xin nhận biết như vậy."],["p","Nam mô Phạm Võng Hội Thượng Phật Bồ"],["p","Tát. (3 lần)"]]},{"t":"Phật Thuyết Kinh Phạm Võng Bồ Tát Tâm Địa Phẩm Phần Dưới","b":[["p","(Nhà Dao Tần, Tam Tạng Pháp Sư Cưu Ma La Thập Hán"],["p","dịch. HT Thích Trí Tịnh Việt dịch.)"]]},{"t":"I. Lô Xá Na Phật","b":[["v",["Bấy giờ, đức Phật Lô Xá Na","vì trong đại chúng lược giảng “Tâm Địa”","như chừng bằng đầu sợi lông","trong số trăm nghìn hằng hà sa","bất khả thuyết pháp môn.","Ngài kết"]],["p","“Tâm Địa đây chính là lời của tất cả Phật thời quá khứ đã giảng,"],["v",["tất cả Phật thời vị lai sẽ giảng","và tất cả Phật thời hiện tại đương giảng.","Cũng là pháp môn mà tất cả Bồ Tát","đã học, sẽ học và đương học."]],["v",["Ta đã từng trăm A Tăng Kỳ kiếp","tu tập tâm địa này,","do đó ta được hiệu là Lô Xá Na.","Chư Phật!","Các Ngài đem lời giảng của ta đây","hầu mở con đường tâm địa","cho hết thảy chúng sanh”."]],["v",["Liền đó,","từ trên Tòa Thiên Quang Sư Tử rực rỡ","nơi thế giới Liên Hoa Đài Tạng,","đức Phật Lô Xá Na","phóng ra những tia sáng.","Trong tia sáng ấy","có tiếng nói với chư Phật","đang ngự trên nghìn cánh sen báu:","“Các Ngài thọ trì","phẩm Tâm Địa Pháp Môn của ta đây,","rồi tuần tự đem giảng lại","cho nghìn trăm ức Thích Ca","cùng tất cả chúng sanh.","Ai nấy đều nên thọ trì đọc tụng","và nhất tâm vâng làm”."]],["v",["Sau khi lãnh thọ","phẩm Tâm Địa Pháp Môn,","chư Phật đang ngự","trên nghìn cánh sen báu","cùng nghìn trăm ức đức Thích Ca","đồng đứng dậy rời khỏi tòa Sư Tử\u0001","Toàn thân của các Ngài","chiếu ra vô số tia sáng.","Trong mỗi tia sáng ấy","đều hóa hiện vô lượng đức Phật,","đồng thời tung lên vô lượng hoa đẹp","xanh, vàng, đỏ, trắng","để cúng dường đức Phật Lô Xá Na.","Cúng dường xong, chư Phật từ tạ trở về.","Khi rời khỏi thế giới Liên Hoa Đài Tạng,","chư Phật vào chánh định","thể tánh hư không hoa quang,","mỗi Ngài trở lại chốn cũ,","dưới cội Bồ Đề nơi cõi Diêm Phù."]],["v",["Sau khi ra khỏi chánh định","thể tánh hư không hoa quang,","đức Phật mới ngự trên tòa","Kim Cương Thiên Quang Vương","và Diệu Quang Đường","mà giảng về Thập Thế Giới Hải."]],["p","Rồi đức Phật giảng pháp Thập Trụ"],["v",["nơi cung Đế Thích,","giảng pháp Thập Hạnh"]],["v",["nơi cung trời Diệm Ma,","giảng pháp Thập Hồi Hướng"]],["v",["nơi cung trời Đâu Suất,","giảng pháp Thập Thiền Định"]],["v",["nơi cung trời Hóa Lạc,","giảng pháp Thập Địa"]],["v",["nơi cung Trời Tha Hóa,","giảng pháp Thập Kim Cương"]],["v",["nơi cõi Sơ Thiền,","giảng pháp Thập Nhẫn"]],["v",["nơi cõi Nhị Thiền,","giảng pháp Thập Nguyện"]],["v",["nơi cõi Tam Thiền,","và sau cùng ở Tứ Thiền","nơi cung của Đại Tự Tại Thiên Vương,"]],["p","đức Phật giảng Phẩm Tâm Địa Pháp Môn mà thuở trước đức Phật Lô Xá Na"],["p","đã giảng ở thế giới Liên Hoa Đài Tạng."],["v",["Tất cả nghìn trăm ức đức Thích Ca","ở nơi Thế giới của mình","đều giảng nói như thế cả.","(Như trong phẩm “Hiền Kiếp” đã nói.)"]]]},{"t":"II. Thích Ca Mâu Ni Phật","b":[["p","Bấy giờ, đức Phật Thích Ca Mâu Ni,"],["p","từ lúc sơ khởi"],["p","hiện thân nơi thế giới Liên Hoa Đài Tạng, rồi qua phương Đông"],["v",["đến tại cung của Thiên Vương,","diễn nói kinh “Ma Thọ Hóa”.","Sau đó, Ngài giáng sanh nơi cõi","Nam Diêm Phù Đề tại nước Ca Tỳ La,","Vua Tịnh Phạn là thân phụ,","và Hoàng Hậu Ma Gia là sanh mẫu,","nhũ danh của Ngài là Tất Đạt Đa."]],["p","Xuất gia bảy năm, ba mươi tuổi thành đạo hiệu Ngài là Thích Ca Mâu Ni Phật."],["v",["Từ Bảo Tòa Kim Cương Hoa Quang","nơi đạo tràng Tịch diệt","nhẫn đến nơi cung","của Đại Tự Tại Thiên Vương,","trong mười nơi ấy","đức Phật tuần tự ngự đến thuyết pháp."]],["v",["Lúc đó,","nhân khi xem bửu tràng mành lưới","của Đại Phạm Thiên Vương,","đức Phật vì đại chúng","mà giảng Kinh Phạm Võng\u0001","Ngài dạy rằng:","“Vô lượng thế giới dường như là lỗ lưới.","Mỗi thế giới đều khác nhau cả,","khác nhau đến số vô lượng.","Giáo pháp của Phật cũng như vậy.”"]],["v",["Đức Phật đã tám nghìn lần","đến thế giới Ta Bà này,","ngự trên Bảo Tòa Kim Cương Hoa Quang","nhẫn đến ngự nơi cung","của Đại Tự Tại Thiên Vương,","lược giảng “Tâm Địa Pháp Môn”","cho cả thảy đại chúng","trong những Pháp Hội ấy."]],["v",["Sau đó từ cung của Thiên Vương,","đức Phật trở xuống","ngự dưới cội Bồ Đề nơi cõi Diêm Phù,","vì tất cả chúng sanh trên quả đất này,","hạng người Phàm ngu tối","mà giảng một giới pháp","Kim Cương Quang Minh Bảo Giới\u0001","Giới Pháp này","là lời thường trì tụng của Phật Lô Xá Na,","khi Ngài mới phát Bồ Đề tâm","trong thời kỳ tu nhân của Ngài.","Giới pháp này"]],["p","cũng chính là bổn nguyện của tất cả Phật, là bổn nguyện của tất cả Bồ Tát"],["p","và là chủng tử của Phật Tánh\u0001"],["v",["Tất cả chúng sanh đều có Phật Tánh.","Tất cả ý thức, sắc, tâm, là tình, là tâm","đều vào trong phạm vi","giới pháp Phật Tánh.","Vì chắc chắn thường có chánh nhân,","nên chắc chắn Pháp Thân thường trụ."]],["v",["Mười Ba La Đề Mộc Xoa như thế","xuất hiện trong đời.","Giới pháp này là chỗ kính trọng thọ trì","của tất cả chúng sanh trong ba thuở."]],["v",["Giờ đây,","đức Phật sẽ vì trong đại chúng này","mà giảng lại Giới Phẩm Vô Tận Tạng,","là Giới Phẩm của tất cả chúng sanh,","bổn nguyện tự tánh thanh tịnh."]],["v",["Nay ta là Lô Xá Na,","Đương ngồi trên đài Liên Hoa.","Trên nghìn cánh sen đơm vòng,","Lại hiện ra nghìn Thích Ca.","Mỗi cánh sen trăm ức cõi,","Một cõi một Phật Thích Ca,","Đều ngồi dưới cội Bồ Đề,","Đồng thời thành chánh giác đạo.","Nghìn trăm ức Phật như vậy,","Lô Xá Na là bổn thân.","Nghìn trăm ức Phật Thích Ca,","Đều đem theo vi trần chúng,","Cùng nhau đến tại chỗ ta,","Để nghe ta tụng Phật Giới.","Ta liền giảng môn Cam Lộ\u0001","Bây giờ nghìn trăm ức Phật,","Trở về đạo tràng của mình,","Đều ngồi nơi cội Bồ Đề,","Tụng mười trọng, bốn mươi tám,","Giới của Bổn Sư Xá Na,","Giới như vầng nhựt nguyệt sáng,","Cũng như chuỗi báu ngọc châu\u0001","Chúng Bồ Tát như vi trần,","Do giới này mà thành Phật,","Đây là đức Xá Na tụng,","Ta đây cũng tụng như vậy.","Các ông tân học Bồ tát,","Phải cung kính thọ trì giới!","Khi thọ trì giới này rồi,","Nên truyền lại cho chúng sanh.","Lắng nghe ta đang trì tụng,","Pháp Ba La Đề Mộc Xoa,","Là giới tạng trong Phật Pháp.","Đại Chúng lòng nên tin chắc:","Các ngươi là Phật sẽ thành,","Ta đây là Phật đã thành.","Thường có lòng tin như vậy,","Thời giới phẩm đã trọn vẹn,","Tất cả những người có tâm,","Đều nên nhiếp hộ Phật Giới,","Chúng sanh nào thọ Phật Giới,","Chính là vào hàng chư Phật.","Đã đồng hàng bậc Đại Giác,","Mới thật là con chư Phật\u0001","Đại Chúng đều nên cung kính,","Chí tâm nghe lời ta tụng."]]]},{"t":"III. Đức Phật Kiết Bồ Tát Giới","b":[["v",["Thuở ấy,","đức Phật Thích Ca Mâu Ni,","lúc mới thành đạo vô thượng chánh giác","trong khi ngồi dưới cội Bồ Đề,","Ngài bắt đầu kiết “Bồ Tát Giới”.","Ngài dạy:","“Hiếu thuận với cha mẹ,","Sư Tăng, Tam Bảo.","Hiếu thuận là pháp chí đạo.","Hiếu gọi là giới, cũng gọi là cấm ngăn ”."]],["v",["Liền đó, từ nơi miệng đức Phật","phóng ra vô lượng tia sáng.","Bấy giờ có đến trăm vạn ức đại chúng,","các Bồ Tát\u0001","mười tám Phạm Thiên\u0001","sáu cõi Trời Dục\u0001","mười sáu đại Quốc vương","đồng chắp tay chí tâm nghe đức Phật","tụng Giới Pháp đại thừa","của tất cả chư Phật."]],["v",["Đức Phật nói với các vị Bồ Tát:","“Nay ta cứ mỗi nửa tháng","tự tụng giới pháp của chư Phật.","Tất cả hàng Bồ Tát sơ phát tâm,","nhẫn đến các Bồ Tát thập Phát Thú,","Thập Trưởng Dưỡng,","Thập Kim Cương,","Thập Địa","cũng tụng giới này.","Vì thế nên giới quang","từ miệng ta phóng ra.","Phóng quang là vì có duyên do,","chớ chẳng phải vô cớ.","Giới Quang ấy chẳng phải màu xanh,","vàng, đỏ, trắng và đen,","chẳng phải sắc pháp,","cũng chẳng phải tâm pháp,","chẳng phải pháp hữu, pháp vô,","cũng chẳng phải pháp nhân, pháp quả.","Nó chính là bổn nguyện của chư Phật,","là căn bản của chúng Phật Tử.","Vì thế nên chúng Phật Tử","phải thọ trì,","phải đọc tụng,","phải học kỹ giới pháp này”."]],["v",["Chúng Phật Tử lắng nghe!","Nếu là người thọ giới Bồ Tát này,","không luận là Quốc Vương, Thái Tử,","các Quan chức","hay Tỳ Kheo, Tỳ Kheo Ni,"]],["p","không luận là chư Thiên cõi Sắc, cõi Dục, không luận là hàng thứ dân,"],["v",["huỳnh môn, dâm nam, dâm nữ","hay hàng nô tỳ,","cũng không luận là tám bộ quỷ thần,","thần Kim Cương hay loài súc sanh","nhẫn đến kẻ biến hóa\u0001","hễ ai nhận hiểu được lời truyền giới","của Pháp Sư thời đều thọ được giới,","và đều gọi là thanh tịnh thứ nhất."]]]},{"t":"IV. Mười Giới Trọng","b":[["v",["Đức Phật bảo các Phật Tử rằng:","Có mười điều giới trọng.","Nếu người thọ giới Bồ Tát","mà không tụng điều giới này,","thời người ấy không phải Bồ Tát,","không phải là Phật Tử.","Chính ta cũng tụng như vậy."]],["v",["Đã lược giảng xong tướng trạng","của giới Bồ Tát. Tất cả Bồ Tát đã học,","sẽ học và đương học. Cần nên học,","hết lòng kính trọng phụng trì.","Đức Phật dạy:"]],["p","1. Giới Sát Sanh"],["v",["Nếu Phật Tử,","hoặc tự mình giết,","bảo người giết,","phương tiện giết,","khen tặng sự giết,","thấy giết mà tùy hỷ,","nhẫn đến dùng bùa chú để giết:","Nhân giết, duyên giết,","cách thức giết, nghiệp giết."]],["v",["Phàm tất cả loài hữu tình có mạng sống","đều không được cố ý giết.","Là Phật Tử,","lẽ ra phải luôn luôn có lòng từ bi,","lòng hiếu thuận,","lập thế cứu giúp tất cả chúng sanh,"]],["p","mà trái lại tự phóng tâm nỡ lòng sát sanh, Phật Tử này phạm “Bồ Tát Ba La Di tội”."],["v",["2. Giới Trộm Cướp","Nếu Phật Tử","tự mình trộm cướp,","bảo người trộm cướp,","phương tiện trộm cướp,","nhẫn đến dùng bùa chú trộm cướp:","Nhân trộm cướp,","duyên trộm cướp,","cách thức trộm cướp,","nghiệp trộm cướp...","Tất cả tài vật có chủ,"]],["p","dầu là của quỷ thần hay của kẻ giặc cướp, nhẫn đến một cây kim, một ngọn cỏ"],["v",["đều không được trộm cướp.","Là Phật Tử,","lẽ ra phải luôn luôn có lòng từ bi,","lòng hiếu thuận,","thường giúp cho mọi người","được phước, được vui,","mà trái lại trộm cướp tài vật của người,","Phật Tử này phạm “Bồ Tát Ba La Di tội”.","3. Giới Dâm"]],["v",["Nếu Phật Tử,","tự mình dâm dục, bảo người dâm dục,","với tất cả phụ nữ, các loài cái, loài mái,","cho đến Thiên Nữ, Quỷ nữ, Thần nữ","cùng phi đạo mà hành dâm:","Nhân dâm dục, duyên dâm dục,","cách thức dâm dục, nghiệp dâm dục.","Là Phật Tử,","đối với tất cả không được cố dâm dục.","Lẽ ra phải có lòng hiếu thuận,","cứu độ tất cả những chúng sanh,","đem pháp thanh tịnh khuyên dạy người,","mà trái lại không có tâm từ bi,","làm cho mọi người sanh việc dâm dục,","không lựa súc sanh, cho đến hành dâm","với mẹ, con, chị, em trong lục thân,","Phật Tử này phạm “Bồ Tát Ba La Di tội”."]],["p","4. Giới Vọng"],["v",["Nếu Phật Tử,","tự mình nói vọng ngữ,","bảo người vọng ngữ,","phương tiện vọng ngữ:","Nhân vọng ngữ,","duyên vọng ngữ,","cách thức vọng ngữ,","nghiệp vọng ngữ.","Nhẫn đến không thấy nói thấy,","thấy nói không thấy,","hoặc thân vọng ngữ, tâm vọng ngữ.","Là Phật Tử, lẽ ra phải luôn luôn","chánh ngữ, chánh kiến,","và cũng làm cho tất cả chúng sanh","có chánh ngữ, chánh kiến,","mà trái lại làm cho mọi người tà ngữ,","tà kiến, tà nghiệp,","Phật Tử này phạm “Bồ Tát Ba La Di tội”."]],["p","5. Giới Bán Rượu"],["v",["Nếu Phật Tử,","tự mình bán rượu,","bảo người bán rượu:","Nhân bán rượu,","duyên bán rượu,","cách thức bán rượu,","nghiệp bán rượu","Tất cả rượu không được bán","Rượu là nhân duyên sanh tội lỗi.","Là Phật Tử,","lẽ ra phải làm cho tất cả chúng sanh","có trí huệ sáng suốt,","mà trái lại đem sự mê say điên đảo","cho tất cả chúng sanh,","Phật Tử này phạm “Bồ Tát Ba La Di tội”."]],["v",["6. Giới Rao Lỗi Của Tứ Chúng","Nếu Phật Tử,","tự miệng rao nói tội lỗi,","của Bồ Tát xuất gia, Bồ Tát tại gia,","Tỳ Kheo, Tỳ Kheo Ni,","hoặc bảo người rao nói những tội lỗi ấy:","Nhân rao nói tội lỗi,","duyên rao nói tội lỗi,","cách thức rao nói tội lỗi,","nghiệp rao nói tội lỗi.","Là Phật Tử, khi nghe những kẻ ác,","ngoại đạo cùng người nhị thừa","nói những điều phi pháp,","trái Luật trong Phật Pháp,","thời phải luôn luôn có lòng từ bi","giáo hóa những kẻ ác ấy"]],["p","cho họ sanh tín tâm lành đối với đại thừa, mà trái lại Phật Tử lại tự mình"],["v",["rao nói những tội lỗi trong Phật Pháp,","Phật Tử này phạm “Bồ Tát Ba La Di tội”.","7. Giới Tự Khen Mình Chê Người"]],["v",["Nếu Phật Tử,","tự khen mình chê người,","cũng bảo người khác","khen ngợi mình chê người:","Nhân chê người,","duyên chê người,","cách thức chê người,","nghiệp chê người.","Là Phật Tử, lẽ ra phải thay thế","chịu những sự khinh chê khổ nhục","cho tất cả chúng sanh,","mình nhận lấy việc xấu,","nhường cho người việc tốt.","Nếu Phật Tử","tự phô trương tài đức của mình","mà dìm che điều hay tốt của người,","làm cho người bị khinh chê,","Phật Tử này phạm “Bồ Tát Ba La Di tội”."]],["p","8. Giới Bỏn Sẻn Thêm Mắng Đuổi"],["v",["Nếu Phật Tử,","tự mình bỏn sẻn,","bảo người bỏn sẻn:","Nhân bỏn sẻn,","duyên bỏn sẻn,","cách thức bỏn sẻn,","nghiệp bỏn sẻn.","Phật Tử khi thấy những người bần cùng","đến cầu xin,","phải cấp cho theo chỗ cần dùng của họ.","Mà Phật Tử lại đem lòng giận ghét,","cho đến không cho một mảy,","có người đến cầu học giáo pháp","cũng chẳng nói một kệ một câu,","lại còn xua đuổi quở mắng,","Phật Tử này phạm “Bồ Tát Ba La Di tội”.","9. Giới Giận Hờn Không Nguôi"]],["v",["Nếu Phật Tử,","tự mình giận, bảo người giận:","Nhân giận, duyên giận,","cách thức giận, nghiệp giận.","Người Phật Tử lẽ ra","phải làm cho tất cả chúng sanh","được những căn lành không gây gổ,","thường có lòng từ bi, lòng hiếu thuận.","Mà trái lại,","đối với trong tất cả chúng sanh,","cho đến trong loài phi chúng sanh,","đem lời ác mạ nhục,","còn thêm dùng tay, chân, dao, gậy","để đánh đập mà vẫn chưa hả dạ,","cho đến nạn nhân kia"]],["p","lấy lời nhỏ nhẹ xin lỗi, cầu sám hối tạ tội, nhưng vẫn còn không hết giận,"],["v",["Phật Tử này phạm “Bồ Tát Ba La Di tội”.","10. Giới Hủy Báng Tam Bảo","Nếu Phật Tử,","tự mình hủy báng Tam Bảo,","xúi người hủy báng Tam Bảo:","Nhân hủy báng,","duyên hủy báng,","cách thức hủy báng,","nghiệp hủy báng.","Phật Tử nghe một lời hủy báng Tam Bảo","của ngoại đạo và kẻ ác, còn đau lòng"]],["p","như ba trăm cây nhọn đâm vào tim mình, huống là tự miệng mình hủy báng!"],["v",["Không có đức tin","và lòng hiếu thuận đối với Tam Bảo,","lại còn giúp sức cho những kẻ ác,","kẻ tà kiến hủy báng nữa,","Phật Tử này phạm “Bồ Tát Ba La Di tội”."]]]},{"t":"V. Đức Phật Kết Răn","b":[["v",["Này các Phật Tử!","Trên đây là mười giới trọng của Bồ Tát,","các Phật Tử cần nên học.","Trong mười giới đó","không nên trái phạm một giới nào cả,","dầu một mảy nhỏ như vi trần,","huống chi phạm đủ cả mười giới ư!","Nếu có người nào trái phạm,","thời người ấy","hiện đời không được phát Bồ Đề tâm,","rồi cũng mất ngôi Quốc Vương,","ngôi Chuyển Luân Vương,","ngôi Tỳ Kheo, Tỳ Kheo Ni,","cũng mất những quả","“Thập Phát Thú”,","“Thập Trưởng Dưỡng”,","“Thập Kim Cương”,","“Thập Địa”,","tất cả diệu quả","Phật Tánh thường trụ đều mất,","đọa trong ba ác đạo,","trong hai kiếp, ba kiếp","chẳng được nghe danh tự","của cha mẹ và Tam Bảo.","Vì thế nên","không được phạm một giới nào cả.","Tất cả Bồ Tát các Ngài đã học,","sẽ học và hiện tại nay học.","Mười giới như thế cần nên học,","hết lòng kính trọng phụng trì.","(Trong phẩm “Bát Vạn Oai Nghi” có giảng rộng.)"]]]},{"t":"VI. 48 Điều Giới Khinh","b":[["v",["Đức Phật bảo các vị Bồ Tát rằng:","Đã giảng mười giới trọng rồi,","nay tôi sẽ nói về","bốn mươi tám giới khinh\u0001"]],["p","1. Giới Không Kính Thầy Bạn"],["v",["Nếu Phật Tử,","lúc sắp lãnh ngôi Quốc Vương,","ngôi Chuyển Luân Vương,","hay sắp lãnh chức quan,","trước nên thọ giới Bồ Tát.","Như thế tất cả quỷ thần","cứu hộ thân Vua và thân các quan.","Chư Phật đều hoan hỷ."]],["v",["Đã đắc giới rồi,","Phật Tử nên có lòng hiếu thuận","và cung kính.","Nếu thấy có bậc Thượng Tọa,","Hòa Thượng, A Xà Lê,"]],["p","những bậc Đại Đức, đồng học, đồng kiến, đồng hạnh đến nhà,"],["v",["phải đứng dậy tiếp rước","lạy chào, hỏi thăm.","Mỗi sự đều đúng như Pháp","mà cúng dường,","hoặc tự bán thân cho đến Quốc thành","con cái, cùng bảy báu trăm vật","để cung cấp các bậc ấy.","Nếu Phật Tử lại sanh lòng kiêu mạn,","sân hận, ngu si,","không chịu tiếp rước lạy chào,","cho đến không chịu y theo Pháp","mà cúng dường,","Phật Tử này phạm “Khinh cấu tội”.","2. Giới Uống Rượu"]],["v",["Nếu Phật Tử cố uống rượu,","mà rượu là thứ làm cho người uống","hay sanh ra vô lượng tội lỗi.","Nếu tự tay trao chén rượu","cho người uống sẽ mang ác báo:","Năm trăm đời không tay,","huống là tự uống.","Cũng chẳng được bảo người","và tất cả chúng sanh uống rượu,","huống là tự mình uống!","Tất cả các thứ rượu,","Phật Tử không được uống.","Nếu mình cố tâm uống","cùng bảo người uống,","Phật Tử này phạm “Khinh cấu tội”."]],["p","3. Giới Ăn Thịt"],["v",["Nếu Phật Tử cố ăn thịt,","tất cả thịt của mọi loài chúng sanh","đều không được ăn.","Luận về người ăn thịt","thời mất lòng đại từ bi,","dứt giống Phật Tánh,","tất cả chúng sanh thấy","đều tránh xa người này.","Người ăn thịt mắc vô lượng tội lỗi.","Vì thế, nên tất cả Phật Tử","không được ăn tất cả thứ thịt","của mọi loài chúng sanh.","Nếu cố ăn thịt,","Phật Tử này phạm “Khinh cấu tội”."]],["p","4. Giới Ăn Ngũ Tân"],["v",["Nếu Phật Tử,","chẳng được ăn loại “Ngũ tân”","– loại hành, hẹ, tỏi, nén và hưng cừ.","Loại ngũ tân này gia vào trong tất cả","thứ thực phẩm đều không được ăn.","Nếu cố ăn,","Phật Tử này phạm “Khinh cấu tội”."]],["p","5. Giới Không Dạy Người Sám Tội"],["v",["Nếu Phật Tử","khi thấy người phạm ngũ giới,","bát giới, thập giới, phá giới,","hay phạm thất nghịch, bát nạn,","tất cả tội phạm giới v.v...","phải khuyên bảo người ấy sám hối.","Nếu Phật Tử chẳng khuyên bảo","người phạm tội sám hối,","lại cùng ở chung, đồng sống chung,","đồng chung Bố Tát, đồng thuyết giới,","mà không cử tội người ấy,","không nhắc người ấy sám hối,","Phật Tử này phạm “Khinh cấu tội”."]],["p","6. Giới Không Cúng Dường Thỉnh Pháp"],["v",["Nếu Phật Tử,","thấy có vị Pháp Sư Đại Thừa","hay những bậc đồng học, đồng kiến,","đồng hạnh Đại Thừa,","từ trăm dặm nghìn dặm","đến nơi Tăng phường, nhà cửa, thành ấp","thời liền đứng dậy rước vào, đưa đi,","lễ bái, cúng dường.","Mỗi ngày ba thời cúng dường,","trăm thức uống ăn, giường ghế,","thuốc men, tất cả đồ cần dùng","giá đáng ba lượng vàng","đều phải cấp hộ cho Pháp Sư.","Mỗi ngày: Sáng, trưa và chiều,","thường thỉnh Pháp Sư thuyết Pháp","và đảnh lễ.","Không hề có lòng sân hận buồn rầu.","Luôn thỉnh Pháp, không mỏi nhàm,","chỉ trọng Pháp chớ không kể thân.","Nếu Phật Tử không như thế","thời phạm “Khinh cấu tội”."]],["p","7. Giới Không Đi Nghe Pháp"],["v",["Nếu Phật Tử,","hàng Tân học Bồ Tát,","phàm nơi nào, chốn nào","có giảng Kinh, Luật,","phải mang Kinh, Luật đến chỗ Pháp Sư","để nghe giảng và thưa hỏi.","Hoặc nơi núi rừng,","trong vườn cây, chùa, nhà v.v...","Tất cả chỗ thuyết pháp đều đến nghe học.","Nếu Phật Tử không đến nơi ấy","để nghe Pháp cùng thưa hỏi,","thời phạm “Khinh cấu tội”."]],["p","8. Giới Có Tâm Trái Bỏ Đại Thừa"],["v",["Nếu Phật Tử,","có quan niệm","trái bỏ Kinh Luật Đại Thừa thường trụ,","cho rằng không phải của Phật nói","mà đi thọ trì Kinh Luật tà kiến","và tất cả cấm giới của Thanh văn","Nhị Thừa cùng ngoại đạo ác kiến,","Phật Tử này phạm “Khinh cấu tội”."]],["p","9. Giới Không Khán Bệnh"],["v",["Nếu Phật Tử,","thấy tất cả người tật bệnh","phải tận tâm cúng dường","như cúng dường Phật.","Trong tám phước điền,","khán bệnh là “Phước điền thứ nhất”.","Nếu như cha mẹ, sư Tăng","cùng đệ tử có bệnh, có tật,","trăm thứ bệnh đau khổ,","đều nên săn sóc cho được lành mạnh,","Phật tử lại vì lòng hờn giận","không chăm nuôi,","nhẫn đến thấy trong tăng phường,","thành ấp, nơi núi rừng đồng nội,","đường xá có người tật bệnh","mà không lo cứu tế,","Phật Tử này phạm “Khinh cấu tội”."]],["p","10. Giới Chứa Khí Cụ Sát Sanh"],["v",["Nếu Phật Tử","không được cất chứa những binh khí,","như dao, gậy, cung, tên, giáo, mác v.v...","cùng những đồ sát sanh","như chài, lưới, rập, bẫy v.v...","Là Phật Tử,","dầu cho đến cha mẹ bị người giết,","còn không báo thù,","huống lại đi giết tất cả chúng sanh!","Không được cất chứa","những khí cụ sát sanh!","Nếu cố cất chứa,","Phật Tử này phạm “Khinh cấu tội”.","Mười giới như thế, cần nên học","và kính trọng phụng trì.","(Trong sáu phẩm sau có giảng rộng.)"]],["v",["11. Giới Đi Sứ","Nếu Phật Tử,","chẳng đặng vì quyền lợi và ác tâm","mà đi thông sứ mạng cho hai nước"]],["p","hiệp hội quân trận, đem binh đánh nhau làm cho vô lượng chúng sanh bị giết hại."],["v",["Là Phật Tử còn không được vào,","cùng qua lại trong quân trận,","huống lại cố làm môi giới chiến tranh.","Nếu cố làm,","Phật Tử này phạm “Khinh cấu tội”.","12. Giới Buôn Bán Phi Pháp","Nếu Phật Tử"]],["p","cố bán người lành, tôi trai, tớ gái, lục súc, buôn bán quan tài, ván cây,"],["v",["đồ đựng thây chết,","còn không được tự mình buôn bán","các thứ ấy, huống lại bảo người.","Nếu cố tự buôn bán,","hay bảo người buôn bán các thứ ấy,","Phật Tử này phạm “Khinh cấu tội”."]],["v",["13. Giới Hủy Báng","Nếu Phật Tử,","vì ác tâm, nơi người tốt,","người lành, Pháp sư, Sư tăng,","hoặc Quốc vương và hàng quý nhân,","vốn vô sự mà hủy báng là","phạm bảy tội nghịch, mười giới trọng.","Với cha mẹ, anh em, lục thân","phải có lòng từ bi, lòng hiếu thuận,","mà trở lại vu khống","cho là phạm tội nghịch, đọa nơi ác đạo,","Phật Tử này phạm “Khinh cấu tội”."]],["p","14. Giới Phóng Hỏa"],["v",["Nếu Phật Tử,","vì tâm ác, phóng hỏa","đốt núi rừng, đồng nội.","Từ tháng tư đến tháng chín phóng hỏa.","Hoặc cháy lan đến nhà cửa,","thành ấp, tăng phường,","ruộng cây của người","và cung điện tài vật của Quỷ thần.","Tất cả chỗ có sanh vật","không được cố thiêu đốt.","Nếu cố thiêu đốt,","Phật Tử này phạm “Khinh cấu tội”."]],["v",["15. Giới Dạy Giáo Lý Ngoài Đại Thừa","Nếu Phật Tử,","từ Phật đệ tử, lục thân,","tất cả thiện tri thức,","đến ngoại đạo ác nhân, đều phải","khuyên bảo thọ trì Kinh Luật Đại Thừa.","Nên giảng cho họ hiểu nghĩa lý","khiến kia phát tâm Bồ Đề,","Thập Phát Thú tâm,","Thập Trưởng Dưỡng tâm,","Thập Kim Cương tâm.","Trong ba mươi tâm ấy,","giảng cho họ hiểu Pháp công dụng","tuần tự của mỗi món.","Mà Phật tử lại vì ác tâm, sân tâm"]],["p","đem Kinh Luật của Thanh Văn Nhị Thừa, cùng các bộ Luận của ngoại đạo tà kiến"],["v",["để dạy ngang cho người,","Phật Tử này phạm “Khinh cấu tội”.","16. Giới Vì Lợi Mà Giảng Pháp Lộn Lạo","Nếu Phật Tử,","phải tận tâm học Kinh Luật","oai nghi đại thừa, thông hiểu nghĩa lý.","Khi thấy có hàng tân học Bồ Tát","từ xa trăm dặm nghìn dặm","đến cầu học Kinh Luật Đại Thừa,","nên đúng như pháp","giảng giải tất cả khổ hạnh,","hoặc đốt thân,","đốt cánh tay, đốt ngón tay.","Nếu không đốt thân","hay cánh tay, ngón tay","cúng dường chư Phật","thời không phải là hàng Bồ Tát xuất gia.","Nhẫn đến xả thịt nơi thân mình","cùng tay chân mà bố thí cho tất cả","những cọp, sói, sư tử đói,","cùng tất cả loài quỷ đói.","Rồi sau mới tuần tự theo căn cơ","của mỗi người mà giảng chánh pháp cho","hàng tân học ấy được mở thông tâm ý.","Nếu Phật tử vì quyền lợi,","đáng dạy mà không dạy,","lại giảng Kinh Luật một cách điên đảo,"]],["p","văn tự lộn xộn không có thứ lớp trước sau thuyết pháp có tính cách"],["v",["hủy báng Tam Bảo,","Phật Tử này phạm “Khinh cấu tội”.","17. Giới Cậy Thế Lực Quyên Tởi","Nếu Phật Tử,","tự mình vì việc ăn uống","tiền của, lợi dưỡng, danh dự","mà thân cận Quốc Vương,","Hoàng Tử cùng các Quan,","nương quyền cậy thế","bức người để lấy tiền của,","lại bảo người khác cũng cầu lợi như vậy.","Tất cả sự cầu lợi ấy gọi là ác cầu, đa cầu,"]],["p","đều không có lòng từ bi, lòng hiếu thuận, Phật Tử này phạm “Khinh cấu tội”."],["v",["18. Giới Không Thông Hiểu Mà Làm Thầy Truyền Giới","Nếu Phật Tử,","phải học mười hai phần Kinh,","thường tụng giới."]],["p","Mỗi ngày sáu thời, nghiêm trì Bồ Tát giới, hiểu rõ nghĩa lý tính Phật Tánh của giới."],["v",["Nếu Phật Tử không hiểu một kệ một câu","cùng nhân duyên của Giới Luật,","mà dối rằng thông hiểu,","đó chính là dối gạt mình","và cũng là dối gạt người khác.","Không hiểu một Pháp,","không biết một Luật","mà lại đi làm Thầy truyền giới cho người.","Phật Tử này phạm “Khinh cấu tội”.","19. Giới Lưỡng Thiệt (Lưỡi Đôi Chiều)"]],["v",["Nếu Phật Tử,","vì ác tâm, thấy Thầy Tỳ Kheo trì giới","tay bưng lư hương, tu hạnh Bồ Tát,","tự đi đâm thọc hai đầu,","cho sanh sự bất hòa","khinh khi người hiền, tạo nhiều tội ác.","Phật Tử này phạm “Khinh cấu tội”.","20. Giới Không Phóng Sanh"]],["v",["Nếu Phật Tử,","vì tâm từ bi mà làm việc phóng sanh.","Tất cả nam tử là cha ta,","tất cả nữ nhân là mẹ ta.","Từ nhiều đời ta đều thác sanh nơi đó.","Vì lẽ ấy nên chúng sanh trong lục đạo","đều là cha mẹ ta.","Nếu giết chúng để ăn thịt,","thời chính là giết cha mẹ ta,","mà cũng là giết thân cũ của ta.","Tất cả chất tứ đại","đều là bổn thân bổn thể của ta,"]],["p","cho nên phải thường làm việc phóng sanh và khuyên bảo người làm."],["v",["Nếu lúc thấy người đời sát sanh,","nên tìm cách cứu hộ cho chúng","được thoát khỏi nạn khổ!","Thường đem giới Bồ Tát","giảng dạy để cứu độ chúng sanh.","Nếu ngày cha mẹ hay anh em chết,","nên thỉnh Pháp Sư","giảng Kinh Luật Bồ Tát giới.","Người chết nhờ phước đức ấy,","hoặc được vãng sanh Tịnh Độ","ra mắt chư Phật,","hay thác sanh trong cõi Trời, cõi Người.","Nếu không làm các điều trên đây,","Phật Tử này phạm “Khinh cấu tội”.","Mười giới như thế cần nên học tập","kính trọng phụng trì.","(Như trong phẩm “Diệt tội” giảng rõ mỗi giới.)","21. Giới Đem Sân Báo Sân Đem Đánh Trả Đánh"]],["v",["Nếu Phật Tử,","không được đem giận trả giận,","đem đánh trả đánh.","Nếu cha mẹ, anh em, hay lục thân","bị người giết cũng chẳng được báo thù,","hoặc quốc chủ bị người thí chết","cũng chẳng được báo thù.","Giết sanh mạng để báo thù sanh mạng,","đó là việc không thuận với hiếu đạo.","Hãy còn không được chứa nuôi tôi tớ,","rồi đánh đập mắng nhiếc chúng,","mỗi ngày tam nghiệp tạo vô lượng tội,","nhất là khẩu nghiệp.","Huống lại cố đi làm tội thất nghịch.","Nếu xuất gia Bồ Tát không có lòng từ bi","cố báo thù, nhẫn đến cố báo thù","cho trong hàng lục thân,","Phật Tử này phạm “Khinh cấu tội”."]],["p","22. Giới Kiêu Mạn Không Thỉnh Pháp"],["p","Nếu Phật Tử,"],["p","mới xuất gia, chưa thông hiểu Kinh Luật, mà tự ỷ mình là trí thức thông minh,"],["v",["hoặc ỷ mình là cao quý, lớn tuổi,","hoặc ỷ mình là dòng sang,","con nhà quyền quý,","hoặc ỷ mình học rộng,","phước to giàu lớn v.v...","rồi sanh lòng kiêu mạn,","không chịu học hỏi Kinh Luật","với các vị Pháp Sư học đạo trước mình.","Vị Pháp Sư ấy hoặc dòng hèn,","con nhà hạ tiện,","tuổi trẻ, nghèo nàn, hèn hạ","hay có tật nguyền","nhưng lại thiệt có đức hạnh","cùng thông hiểu nhiều Kinh Luật."]],["p","Hàng tân học Bồ Tát không được nhìn vào dòng giống vị Pháp Sư mà không chịu"],["v",["đến học đạo lý đại thừa với vị ấy,","Phật Tử nếu như vậy","thời phạm “Khinh cấu tội”.","23. Giới Khinh Ngạo Không Tận Tâm Dạy","Nếu Phật Tử,","sau khi Phật diệt độ,","lúc có tâm tốt muốn thọ giới Bồ Tát,","thời đối trước tượng Phật","cùng tượng Bồ Tát mà tự nguyện thọ giới.","Nên ở trước tượng Phật và tượng Bồ Tát","sám hối trong bảy ngày,","hễ được thấy hảo tướng là đắc giới.","Như chưa thấy hảo tướng","thời phải sám hối 14 ngày, 21 ngày,","hay đến cả năm, cầu thấy được hảo tướng.","Khi được thấy hảo tướng rồi,","thời được đối trước tượng Phật,","Bồ Tát mà thọ giới.","Như chưa thấy hảo tướng"]],["p","thời dầu có đối trước tượng Phật thọ giới, vẫn không gọi là đắc giới."],["v",["Nếu đối trước vị Pháp Sư","đã thọ giới Bồ Tát mà thọ giới,","thời không cần thấy hảo tướng.","Tại sao vậy? Vì vị Pháp Sư ấy","là chư sư truyền giới cho nhau,","nên không cần hảo tướng.","Hễ đối trước vị Pháp Sư ấy mà thọ giới","liền đắc giới,","do vì hết lòng kính trọng nên đắc giới.","Nếu ở trong vòng nghìn dặm,","mà tìm không được vị Pháp Sư","truyền giới, thời Phật Tử được phép","đối trước tượng Phật và Bồ Tát","mà tự nguyện thọ giới Bồ Tát,","nhưng cần phải thấy hảo tướng.","Nếu các vị Pháp Sư ỷ mình"]],["p","thông Kinh Luật cùng giới pháp đại thừa, kết giao với các nhà quyền quý,"],["v",["khi có hàng tân học Bồ Tát","đến cầu học nghĩa Kinh, Luật,","lại giận ghét, hay khinh ngạo,","không chịu tận tâm chỉ bảo,","vị này phạm “Khinh cấu tội”.","24. Giới Không Tập Học Đại Thừa"]],["v",["Nếu Phật Tử,","có Kinh Luật Đại Thừa Pháp","chánh kiến, chánh tánh,","chánh pháp thân của Phật,","mà không chịu siêng học siêng tu,","lại bỏ bảy của báu,","trở lại học những sách luận tà kiến","của nhị thừa, ngoại đạo, thế tục,","đó là làm mất giống Phật,","là nhân duyên chướng đạo,","chẳng phải thực hành đạo Bồ Tát.","Nếu cố làm như vậy,","Phật Tử này phạm “Khinh cấu tội”.","25. Giới Tri Chúng Vụng Về"]],["v",["Nếu Phật Tử,","sau khi Phật diệt độ","làm vị Pháp Sư, Giảng Sư,","Luật Sư, Thiền Sư","Thủ Tọa, Tri Sự, Tri Khách,","phải có lòng từ bi","khéo hòa giải trong chúng,","khéo giữ gìn tài vật của Tam Bảo,","chớ dùng vô độ như của riêng mình,","mà trở lại khuấy chúng","gây gổ, kình chống,","lung lòng xài của Tam Bảo,","Phật Tử này phạm “Khinh cấu tội”."]],["p","26. Giới Riêng Thọ Lợi Dưỡng"],["v",["Nếu Phật Tử","ở trước trong Tăng phường,","lúc sau thấy có khách","Bồ Tát Tỳ Kheo mới đến","hoặc nơi thành ấp,","nhà cửa của Tăng hay của Vua,","nhẫn đến chỗ kiết hạ an cư","cùng trong đại hội...","chư Tăng ở trước phải đón rước đưa đi,","cung cấp cho những đồ uống ăn,","đồ nằm, thuốc men,","nhà, phòng, giường, ghế v.v...","Nếu tự mình không có,","thì phải bán thân, bán con cái,","lóc thịt thân mình mà bán, để sắm","đồ cung cấp cho những khách Tăng ấy.","Nếu có thí chủ đến thỉnh","chúng Tăng thọ trai,","khách Tăng có dự phần,","vị Tri Sự phải theo thứ tự","phái Khách Tăng đi thọ trai.","Nếu chư Tăng ở trước riêng đi thọ trai","mà không phái Khách Tăng đi,","thời vị Tri Sự mắc vô lượng tội,","không đáng là hàng Sa Môn","không phải con dòng họ Thích,","nào khác gì loài súc sanh.","Phật Tử này phạm “Khinh cấu tội”.","27. Giới Thọ Biệt Thỉnh"]],["v",["Nếu Phật Tử,","tất cả chẳng được nhận của cúng dường","dành riêng về mình.","Của cúng dường này","thuộc về thập phương Tăng,","nếu nhận riêng","thời là lấy của thập phương Tăng","đem về phần mình.","Và của vật trong tám phước điền:","Chư Phật, Thánh Nhân, các Sư Tăng,","cha mẹ và người bệnh,","tự mình riêng nhận dùng.","Phật Tử này phạm “Khinh cấu tội”."]],["p","28. Giới Biệt Thỉnh Tăng"],["v",["Nếu Phật Tử","có những hàng Bồ Tát xuất gia,","Bồ Tát tại gia và tất cả đàn việt","lúc muốn thỉnh Tăng để cúng dường","cầu nguyện,","nên vào Tăng phường thưa với vị Tri Sự.","Vị Tri Sự bảo rằng:","Theo thứ tự mà thỉnh","thời được Thập Phương Hiền Thánh Tăng.","Người đời riêng thỉnh","năm trăm vị A La Hán Bồ Tát Tăng","vẫn không bằng theo thứ tự","thỉnh một phàm phu Tăng.","Trong giáo pháp của bảy đức Phật","đều không có pháp thỉnh Tăng riêng.","Nếu thỉnh Tăng riêng","đó là pháp của ngoại đạo,","là không thuận với hiếu đạo.","Nếu Phật Tử cố thỉnh riêng","thời phạm “Khinh cấu tội”."]],["p","29. Giới Tà Mạng Nuôi Sống"],["v",["Nếu Phật Tử","dùng ác tâm","vì lợi dưỡng buôn bán nam sắc, nữ sắc,","tự tay làm đồ ăn, tự xay, tự giã,","xem tướng, bàn mộng,","đoán sẽ sanh trai hay gái,","bùa chú, pháp thuật, nghề nghiệp,","phương pháp nuôi ó và chó săn,","hòa hiệp trăm thứ thuốc độc,","nghìn thứ thuốc độc,","độc rắn, độc sanh kim,","sanh ngân, độc sâu cổ,","đều không có lòng từ bi, lòng hiếu thuận.","Nếu cố làm các điều như thế,","Phật Tử này phạm “Khinh cấu tội”."]],["v",["30. Giới Quản Lý Cho Bạch Y","Nếu Phật Tử","vì ác tâm, tự mình hủy báng Tam Bảo,"]],["p","giả tuồng kính mến, miệng thì nói không, mà hành vi lại ở trong có,"],["v",["làm Quản lý cho hàng bạch y,","vì hàng bạch y làm mai, làm mối","cho nam, cho nữ giao hội dâm sắc","gây thành các nghiệp kiết phược,","những ngày lục trai trong mỗi tháng,","ba tháng trường trai trong mỗi năm,","làm việc sát sanh, trộm cướp,","phá trai, phạm giới.","Phật Tử này phạm “Khinh cấu tội”.","Mười giới như thế, cần nên học","hết lòng kính trọng phụng trì.","(Trong phẩm “Chế Giới” có giảng rõ.)","31. Giới Không Mua Chuộc","Nếu Phật Tử,","sau khi Phật diệt độ, ở trong đời ác,","thấy hàng ngoại đạo, bọn giặc cướp","cùng tất cả người ác"]],["p","đem bán hình tượng Phật, Bồ Tát, cha mẹ, đem bán Kinh Luật,"],["v",["đem bán Tỳ Kheo, Tỳ Kheo Ni,","cùng người hành đạo Bồ Tát,","kẻ phát tâm Bồ Đề,","để làm tay sai cho các quan","hay làm tôi tớ cho mọi người.","Phật Tử thấy những sự như thế,","nên có lòng từ bi tìm cách cứu vớt.","Nếu không đủ sức,","Phật Tử phải đi quyên tiền các nơi","để chuộc hình tượng Phật, Bồ Tát","và tất cả Kinh Luật,","chuộc Tỳ Kheo, Tỳ Kheo Ni,","người tu hạnh Bồ Tát,","kẻ phát tâm Bồ Đề.","Nếu không chuộc,","Phật Tử này phạm “Khinh cấu tội”.","32. Giới Tổn Hại Chúng Sanh"]],["v",["Nếu Phật Tử,","không được buôn bán dao gậy, cung tên","những khí giới sát sanh.","Không được chứa cân non giạ thiếu.","Không được nương thế lực quan quyền","mà lấy tài vật của người.","Không được ác tâm trói buộc người,","và phá hoại việc thành công của người.","Không được nuôi mèo, chồn, heo, chó.","Nếu cố làm các điều trên,","Phật Tử này phạm “Khinh cấu tội”."]],["v",["33. Giới Tà Nghiệp Giác Quán","Nếu Phật Tử,","không được vì ác tâm","đi xem tất cả nam nữ v.v... đánh nhau,"]],["p","hay quân trận, binh tướng, giặc cướp v.v... đấu chiến nhau."],["v",["Cũng chẳng được đi xem hát,","nghe nhạc, chơi cờ,","đánh bạc, đá cầu, đá bóng v.v...","cho đến bói xủ.","Chẳng được làm tay sai cho kẻ trộm cướp.","Nếu cố làm các điều trên,","Phật Tử này phạm “Khinh cấu tội”.","34. Giới Tạm Bỏ Bồ Đề Tâm"]],["v",["Nếu Phật Tử,","ngày đêm sáu thời","đọc tụng giới Bồ Tát này.","Nên giữ gìn giới luật","trong tất cả khi đi đứng nằm ngồi,","vững chắc như kim cương,","như đeo trái nổi để qua biển lớn,","như các Tỳ Kheo bị cột bằng dây cỏ.","Thường có tín tâm lành đối với đại thừa.","Tự biết rằng mình là Phật chưa thành,","còn chư Phật là Phật đã thành,","rồi phát Bồ Đề Tâm","và giữ vững không thối chuyển.","Nếu có một tâm niệm xu hướng","theo Nhị Thừa hay ngoại đạo,","Phật Tử này phạm “Khinh cấu tội”."]],["v",["35. Giới Không Phát Nguyện","Nếu Phật Tử,","nên phát những điều nguyện lớn:"]],["p","Nguyện ở hiếu thuận với cha mẹ, Sư Tăng Nguyện đặng gặp được thầy tốt"],["v",["Bạn Thiện Tri Thức","Thường dạy bảo cho tôi","các Kinh Luật Đại Thừa:","“Thập Phát Thú”,","“Thập Trưởng Dưỡng”,","“Thập Kim Cương”,","“Thập Địa”,","cho tôi hiểu rõ tu hành đúng chánh pháp.","Nguyện giữ vững giới của Phật:","Thà chết chớ không chịu phai lòng.","Nếu tất cả Phật Tử"]],["p","không phát những điều nguyện trên đây thời phạm “Khinh cấu tội”."],["p","36. Giới Không Phát Thệ"],["v",["Nếu Phật Tử","khi đã phát","mười điều nguyện lớn trên đây rồi,","phải giữ gìn giới cấm của Phật."]],["v",["Tự thệ rằng:","Thà nhảy vào đống lửa, hố sâu, núi đao,","quyết không cùng với tất cả người nữ","làm điều bất tịnh để phạm điều cấm","trong Kinh Luật của Tam Thế chư Phật."]],["v",["Lại thệ rằng:","Thà lấy lưới sắt nóng","quấn thân mình cả nghìn lớp,","quyết không để thân này phá giới","mà thọ những đồ y phục","của tín tâm đàn việt."]],["v",["Thà chịu nuốt hòn sắt cháy đỏ","và uống nước đồng sôi","mãi đến trăm nghìn kiếp","quyết không để miệng này phá giới","mà ăn các thứ thực phẩm","của tín tâm đàn việt."]],["v",["Thà nằm trên đống lửa lớn,","trên tấm sắt nóng,","quyết không để thân này phá giới","mà nhận lấy các thứ giường ghế","của tín tâm đàn việt."]],["v",["Thà trong một hai kiếp","chịu cho cả trăm gươm giáo","đâm vào mình,","quyết không để thân này phá giới","mà thọ các thứ thuốc men","của tín tâm đàn việt."]],["v",["Thà nhảy vào vạc dầu sôi","trong trăm nghìn kiếp","quyết không để thân này phá giới","mà lãnh những phòng nhà, ruộng vườn,","đất đai của tín tâm đàn việt."]],["v",["Lại phát thệ rằng:","Thà dùng chày sắt","đập thân này từ đầu tới chân","nát như tro bụi,","quyết không để thân này phá giới","mà thọ sự cung kính lễ bái","của tín tâm đàn việt."]],["v",["Lại phát thệ rằng:","Thà lấy trăm nghìn lưỡi gươm giáo","khoét đôi mắt mình","quyết không đem tâm phá giới này","mà nhìn xem sắc đẹp của người."]],["v",["Thà lấy trăm nghìn dùi sắt","đâm thủng lỗ tai mình","trải trong một hai kiếp,","quyết không đem tâm phá giới này","mà nghe tiếng tốt giọng hay."]],["v",["Thà lấy trăm nghìn lưỡi dao","cắt bỏ lỗ mũi mình,","quyết không đem tâm phá giới này","mà ngửi các mùi thơm."]],["v",["Thà lấy trăm nghìn lưỡi dao","cắt đứt lưỡi mình,","quyết không đem tâm phá giới này,","mà ăn các thức tịnh thực của người."]],["v",["Thà lấy búa bén","chặt chém thân thể mình,","quyết không đem tâm phá giới này","mà tham mặc đồ tốt."]],["v",["Lại phát nguyện:","Nguyện cho tất cả chúng sanh","đều được thành Phật."]],["v",["Nếu Phật Tử","không phát những điều thệ này,","thời phạm “Khinh cấu tội”."]],["v",["37. Giới Vào Chỗ Hiểm Nạn","Nếu Phật Tử,","mỗi năm phải hai kỳ hành đầu đà,","mùa Đông, mùa Hạ","thời ngồi thiền, kiết hạ an cư.","Thường dùng nhành dương, nước tro,","ba y, bình bát,","tọa cụ, tích trượng,","hộp lư hương, đãy lược nước,","khăn tay, con dao,","đá lửa, cái nhíp,","giường dây, kinh luật,","tượng Phật, tượng Bồ Tát.","Khi Phật tử hành đầu đà","cùng lúc du phương","đi lại trăm dặm, nghìn dặm,","mười tám món này mang luôn bên mình.","Đây là hai kỳ hành đầu đà trong mỗi năm:"]],["p","Từ rằm tháng Giêng đến rằm tháng Ba, và từ rằm tháng Tám đến rằm tháng Mười."],["v",["Trong hai kỳ hành đầu đà","luôn mang theo mình mười tám món ấy","như chim hai cánh."]],["v",["Nếu đến ngày Bố tát,","hàng tân học Phật tử,","mỗi nửa tháng luôn Bố tát,","tụng mười giới trọng","và bốn mươi tám giới khinh.","Lúc tụng giới, nên ở trước tượng Phật","và Bồ Tát mà tụng.","Chỉ có một người Bố Tát","thời một người tụng,","nếu hai người, ba người","nhẫn đến trăm nghìn người","cũng một người tụng,","còn bao nhiêu người thời lắng nghe.","Người tụng ngồi cao,","người nghe ngồi thấp.","Mỗi người đều đắp y hoại sắc","chín điều, bảy điều và năm điều.","Trong lúc Kiết Hạ an cư","cũng phải mỗi việc đúng theo phép tắc."]],["v",["Lúc hành đầu đà","chớ đi đến chỗ có tai nạn,","cõi nước hiểm ác, nhà vua hung bạo,","đất đai gập ghềnh, cỏ cây rậm rạp,"]],["p","chỗ có giống sư tử, cọp, sói, cùng lụt bão, nạn cháy, giặc cướp,"],["v",["đường xá có rắn rít...","Tất cả nơi hiểm nạn ấy","điều không được đến.","Chẳng những lúc hành đầu đà,","mà lúc kiết hạ, an cư","cũng không được vào","những chỗ hiểm nạn ấy.","Nếu cố ý vào những nơi ấy,","Phật Tử này phạm “Khinh cấu tội”.","38. Giới Trái Thứ Tự Tôn Ty","Nếu Phật Tử,","phải theo thứ tự đúng pháp mà ngồi:","Người thọ giới trước thời ngồi trước,","người thọ giới sau thời ngồi sau.","Không luận già, trẻ,","Tỳ Kheo, Tỳ Kheo Ni,","người sang như Quốc Vương, Hoàng Tử,","nhẫn đến kẻ hèn như","Huỳnh môn, tôi tớ v.v...","tất cả đều nên theo thứ tự mà ngồi:","Người thọ giới trước thời ngồi trước,","người thọ giới sau thời ngồi sau.","Không được như hàng ngoại đạo, si mê,"]],["p","hoặc già, hoặc trẻ, ngồi trước sau lộn xộn không có thứ tự,"],["v",["không khác cách ngồi của bọn binh nô.","Trong Phật Pháp của Ta,","hễ người thọ giới trước thời ngồi trước,","còn người thọ giới sau thời ngồi sau.","Nếu Phật Tử","không theo thứ tự đúng pháp mà ngồi,","thời phạm “Khinh cấu tội”.","39. Giới Không Tu Phước Huệ","Nếu Phật Tử,"]],["p","thường phải khuyến hóa tất cả mọi người kiến tạo Tăng Phường"],["v",["nơi núi rừng, vườn ruộng,","xây dựng Phật Tháp,","chỗ an cư, tọa thiền","trong mùa Đông, mùa Hạ,","tất cả những cơ sở hành đạo","đều nên kiến tạo.","Người Phật Tử phải giảng thuyết Kinh","Luật Đại Thừa cho tất cả chúng sanh.","Lúc tật bệnh, nước có nạn, có giặc,","ngày cha mẹ, anh em,","Hòa Thượng, A Xà Lê khuất tịch,"]],["p","và mỗi tuần thất, nhẫn đến bảy tuần thất, cũng nên giảng thuyết"],["v",["Kinh Luật Đại Thừa.","Tất cả những Trai hội cầu nguyện,","những lúc đi làm ăn,","những khi có tai nạn, lụt bão, hỏa hoạn,"]],["p","ghe thuyền trôi giạt nơi sông to biển lớn, gặp quỷ La Sát v.v..."],["v",["đều cũng đọc tụng Kinh Luật Đại Thừa.","Nhẫn đến tất cả tội báo,","tam ác, bát nạn, thất nghịch,","gông cùm xiềng xích trói buộc tay chân,","hoặc người nhiều dâm, nhiều sân,","nhiều ngu si, nhiều tật bệnh,","đều nên giảng Kinh Luật Đại Thừa này.","Nếu hàng tân học Phật Tử","không thực hành như trên đây,","thời phạm “Khinh cấu tội”.","Chín giới như thế cần nên học,","hết lòng kính trọng phụng trì.","(Trong phẩm “Phạm Đàn” có giảng rộng)","40. Giới Không Bình Đẳng Truyền Giới","Nếu Phật Tử,","lúc cho người thọ giới","không được lựa chọn.","Tất cả hàng Quốc Vương, Hoàng Tử,","các Quan, Tỳ Kheo, Tỳ Kheo Ni,","tín nam, tín nữ,","dâm nam, dâm nữ,","Phạm Thiên trong mười tám cõi Sắc,","Thiên Tử trong sáu cõi dục,","người thiếu căn, hai căn,","huỳnh môn, tôi tớ","và tất cả Quỷ Thần đều được thọ giới.","Tất cả y phục, ngọa cụ"]],["p","nên bảo phải hòa màu: Xanh, đỏ, đen, tím nhuộm thành hoại sắc cho hiệp với đạo."],["v",["Trong tất cả quốc độ,","theo y phục của người trong nước mặc,","y phục của thầy Tỳ Kheo đều phải khác","với y phục của người thế tục."]],["v",["Khi ai muốn thọ Bồ Tát giới,","vị Sư phải hỏi rằng:","Trong đời này","ngươi có phạm tội thất nghịch chăng?","Bồ Tát Pháp Sư không được cho","người phạm tội thất nghịch","thọ giới trong đời này."]],["v",["Đây là tội thất nghịch:","Ác tâm làm thân Phật chảy máu,","hại bậc Thánh Nhân,","giết cha,","giết mẹ,","giết Hòa Thượng,","giết A Xà Lê,","phá Yết Ma Tăng,","chuyển Pháp Luân Tăng."]],["v",["Nếu phạm tội thất nghịch,","thời hiện đời không đắc giới.","Ngoài ra, tất cả người đều được thọ giới.","Theo pháp của người xuất gia,","không lạy Quốc Vương, cha mẹ,","lục thân và quỷ thần."]],["p","Phàm hễ ai nhận hiểu lời nói của Pháp Sư đều được thọ giới."],["v",["Mà có người từ trăm dặm","nghìn dặm đến cầu Pháp,","nếu Bồ Tát Pháp Sư vì ác tâm, sân tâm,","mà không mau mắn","truyền giới Bồ Tát cho người ấy,","thời phạm “Khinh cấu tội”.","41. Giới Vì Lợi Làm Thầy"]],["v",["Nếu Phật Tử,","giáo hóa người","sanh lòng tin tưởng Pháp đại thừa,","Bồ Tát làm Pháp Sư giáo giới cho người.","Lúc thấy có người muốn thọ giới Bồ Tát,","nên bảo người ấy thỉnh hai Đại Sư:","Hòa Thượng và A Xà Lê."]],["v",["Phải hỏi người ấy","có phạm tội thất nghịch không?","Nếu người ấy hiện đời","có phạm tội thất nghịch, thời Pháp Sư","không được cho người ấy thọ giới.","Như không phạm tội thất nghịch","thời cho thọ giới.","Nếu có phạm trong mười giới trọng,","phải bảo người ấy sám hối,","đối trước tượng Phật và Bồ Tát.","Ngày đêm sáu thời tụng giới Bồ Tát","tha thiết đảnh lễ tam thế chư Phật","cho được thấy hảo tướng.","Sám hối như thế trong bảy ngày","mười bốn ngày,","hai mươi mốt ngày,","nhẫn đến trọn năm","mãi đến chừng nào thấy được hảo tướng.","Đây là hảo tướng:","Thấy Phật đến xoa đầu mình,","thấy hào quang,","thấy hoa báu v.v... các thứ cảnh tượng lạ.","Thấy được những hảo tướng ấy","là triệu chứng tội đã tiêu diệt.","Nếu không được thấy hảo tướng,","dầu có sám hối vẫn vô ích.","Người này hiện đời cũng không đắc giới,","nhưng được tăng ích thọ giới."]],["v",["Nếu là người phạm","trong bốn mươi tám điều giới khinh,","đối thú sám hối, thời tội được tiêu diệt,","không phải như tội thất nghịch."]],["v",["Vị Pháp Sư giáo giới","ở trong những pháp này phải hiểu rõ.","Nếu không hiểu Kinh Luật Đại Thừa,","những giới khinh, giới trọng,","hành tướng phải, chẳng phải,","không hiểu đệ nhất nghĩa đế,","tập chủng tánh,","trưởng dưỡng tánh,","tánh chủng tánh,","bất khả hoại tánh,","đạo chủng tánh,","chánh pháp tánh.","Những quán hạnh đa, thiểu, xuất, nhập","của trong các pháp đó,","cùng mười chi thiền, tất cả pháp hạnh,","mỗi mỗi đều không thông hiểu.","Phật tử vì tài lợi, vì danh tiếng,","cầu quấy, cầu nhiều, tham đệ tử đông","nên giả tuồng là mình hiểu biết","tất cả Kinh Luật để được cúng dường","đó là tự dối mình","mà cũng khi dối người khác."]],["p","Nếu cố làm Giới Sư truyền giới cho người, Phật Tử này phạm “Khinh cấu tội”."],["v",["42. Giới Vì Người Ác Giảng Giới","Nếu Phật Tử,","không được vì tài lợi","mà đem đại giới của chư Phật đây,","nói với người chưa thọ giới Bồ Tát,","hoặc với hàng ngoại đạo,","những người tà kiến... trừ Quốc Vương,","ngoài ra không được nói với tất cả","hạng người ấy.","Những hạng người ấy chẳng thọ giới","của Phật, gọi là súc sanh,"]],["p","đời đời sanh ra không gặp được Tam Bảo, như cây đá, không có tâm thức,"],["v",["gọi là ngoại đạo, bọn tà kiến,","nào khác cây cối.","Với những hạng người tà ác ấy,","nếu Phật Tử giảng nói","giới pháp của chư Phật,","thời phạm “Khinh cấu tội”.","43. Giới Cố Móng Tâm Phạm Giới","Nếu Phật Tử,","do đức tin mà xuất gia,","thọ chánh giới của Phật,","lại cố móng tâm hủy phạm giới pháp,"]],["p","thời không được thọ lãnh đồ cúng dường của tất cả đàn việt,"],["v",["cũng không được đi trên đất","của Quốc dân,","không được uống nước của Quốc dân.","Năm nghìn Đại Quỷ luôn đứng án trước","mặt người đó mà gọi là “Gã bợm giặc”."]],["p","Nếu khi đi vào trong phòng nhà thành ấp, các Quỷ thường theo chà quét dấu chân"],["v",["của người ấy.","Tất cả người đời đều mắng người ấy","là kẻ giặc trong Phật Pháp.","Hết thảy chúng sanh đều không muốn","nhìn ngó người ấy.","Người phạm giới,","khác nào loài súc sanh, cây cỏ.","Nếu cố phá hủy giới pháp của Phật,","Phật Tử này phạm “Khinh cấu tội”.","44. Giới Không Cúng Dường Kinh Luật"]],["v",["Nếu Phật Tử,","phải thường nhất tâm thọ trì","đọc tụng Kinh Luật Đại Thừa,","dùng giấy, vải, hàng, lụa,","thẻ tre, vỏ cây,","cho đến lột da làm giấy,","chích máu làm mực,","lấy tủy làm nước,","chẻ xương làm viết,","để biên chép Kinh Luật,","dùng vàng bạc, cùng hương hoa vô giá","và tất cả châu báu làm hộp, rương,","đựng những quyển Kinh Luật.","Nếu không y theo Pháp","mà cúng dường Kinh Luật,","Phật Tử này phạm “Khinh cấu tội”."]],["v",["45. Giới Không Giáo Hóa Chúng Sanh","Nếu Phật Tử,","nên có lòng đại bi,","khi vào trong tất cả nhà cửa, thành ấp,","thấy những loài chúng sanh,","phải xướng lên rằng:","“Các ngươi đều nên thọ","Tam Quy và Thập Giới”."]],["p","Nếu gặp trâu, bò, chó, ngựa, heo, dê, v.v... nên tâm nghĩ miệng nói:"],["v",["“Các ngươi là súc sanh,","nên phát tâm Bồ Đề”.","Khi Phật tử đi đến núi rừng, sông,","đồng nội cùng tất cả chỗ,","đều làm cho hết thảy chúng sanh","phát tâm Bồ Đề.","Nếu Phật Tử","không phát tâm giáo hóa chúng sanh,","thời phạm “Khinh cấu tội”.","46. Giới Thuyết Pháp Không Đúng Pháp","Nếu Phật Tử,","thường nên có lòng đại bi","phát tâm giáo hóa.","Lúc vào nhà đàn việt sang giàu,","cùng trong tất cả chúng hội,","không được đứng thuyết pháp","cho hàng bạch y.","Phải ngồi trên tòa cao","trước chúng bạch y.","Vị Tỳ Kheo Pháp Sư không được","đứng dưới đất thuyết pháp cho tứ chúng."]],["p","Khi thuyết pháp, vị Pháp Sư ngồi tòa cao, dùng hương hoa cúng dường,"],["v",["còn tứ chúng, hàng thính giả,","thời ngồi dưới thấp.","Đối với Pháp Sư phải hiếu thuận","như hiếu thuận với cha mẹ, Sư trưởng,","như Bà La Môn thờ lửa.","Nếu Phật Tử thuyết pháp mà không đúng như pháp","thời phạm “Khinh cấu tội”.","47. Giới Chế Hạn Phi Pháp"]],["v",["Nếu Phật Tử,","đều đã có lòng tin thọ giới của Phật,","hoặc Quốc Vương, Hoàng tử, các Quan,","bốn bộ đệ tử","tự ỷ thế lực cao quý,","phá diệt giới luật Phật Pháp,","lập ra điều luật chế,","hạn chế bốn bộ đệ tử của Phật,","không cho xuất gia hành đạo,","cũng không cho tạo lập hình tượng Phật","và Bồ Tát, cùng Tháp và Kinh Luật.","Lại đặt ra chức Quan đổng lý","hạn chế tứ chúng, và lập bộ sổ ghi số","Tăng Tỳ Kheo Bồ Tát đứng dưới đất","còn Bạch y ngồi tòa cao, làm nhiều việc","phi pháp như binh nô thờ chủ.","Hàng Bồ Tát này","chính nên được mọi người cúng dường,","mà trở lại bắt làm tay sai","của các Quan chức,","thế là phi pháp phi luật.","Nếu Quốc vương và các Quan","có lòng tốt thọ giới của Phật,","chớ làm những tội phá Tam Bảo ấy.","Nếu cố làm, thời phạm “Khinh cấu tội”."]],["p","48. Giới Phá Diệt Phật Pháp"],["v",["Nếu Phật Tử,","do lòng tốt mà xuất gia,","lại vì danh tiếng cùng tài lợi,","giảng thuyết giới của Phật","cho Quốc Vương và các Quan,","làm những sự gông trói các Tỳ Kheo,","Tỳ Kheo Ni, người thọ giới Bồ Tát","như cách của ngục tù và binh nô.","Như trùng trong thân Sư tử","tự ăn thịt Sư tử,","chớ chẳng phải trùng ở ngoài đến ăn.","Cũng thế,","các Phật Tử tự hủy phá Phật Pháp,","không phải ngoại đạo","hay Thiên Ma phá được."]],["v",["Người đã thọ giới của Phật,","nên hộ trì giới luật của Phật","như ấp yêu con một,","như kính thờ cha mẹ,","không được hủy phá."]],["p","Người Phật Tử"],["p","khi nghe ngoại đạo, người ác"],["p","dùng lời xấu hủy báng giới pháp của Phật, thời đau đớn không khác nào cả ba trăm"],["v",["cây giáo nhọn đâm vào tim mình,","hay cả nghìn lưỡi dao,","cả vạn cây gậy đánh bổ vào thân mình."]],["p","Thà tự cam vào ở địa ngục đến trăm kiếp, chớ không muốn nghe lời hủy báng"],["v",["giới pháp của Phật do bọn người ác.","Huống là không lòng hiếu thuận,","tự mình hủy phá giới pháp của Phật,","hay làm nhân duyên bảo người khác hủy","phá.","Nếu cố phá giới pháp,","Phật Tử này phạm “Khinh cấu tội”.","Chín giới như vậy, cần nên học,","hết lòng kính trọng phụng trì."]]]},{"t":"VII. Tổng Kết","b":[["v",["Đức Phật dạy:","Các Phật Tử!","Đó là bốn mươi tám điều giới khinh,","các người phải thọ trì.","Chư Bồ Tát thuở đời quá khứ đã tụng,","chư Bồ Tát thuở đời vị lai sẽ tụng,","chư Bồ Tát hiện tại đương tụng."]],["v",["Các Phật Tử lắng nghe! Mười giới trọng,","bốn mươi tám giới khinh đây,","chư Phật trong ba đời đã tụng,","sẽ tụng và hiện đương tụng.","Nay ta cũng tụng như vậy."]]]},{"t":"VIII. Lưu Thông","b":[["v",["Đức Phật phán tiếp:","Tất cả Đại Chúng,","Quốc Vương, Vương Tử, các Quan,","Tỳ Kheo, Tỳ Kheo Ni,","tín nam, tín nữ thảy,","những người thọ trì giới Bồ Tát,","nên phải thọ trì đọc tụng","giảng thuyết biên chép","quyển giới pháp Phật Tánh thường trụ","để lưu thông mãi mãi."]],["v",["Tất cả chúng sanh xoay vần","truyền dạy lẫn nhau không dứt.","Do đây, được gặp chư Phật,","được chư Phật trao tay.","Đời đời khỏi hẳn ba ác đạo","và tám chỗ nạn.","Thường được thác sanh trong loài người, hay cõi Trời\u0001"]],["v",["Nay Ta ở dưới cội Bồ Đề này,","lược giảng giới pháp của chư Phật.","Tất cả đại chúng phải nhất tâm học","Ba La Đề Mộc Xoa, hoan hỷ phụng hành.","Như phần “Khuyến Học” trong phẩm","“Vô Tướng Thiên Vương”","mỗi mỗi đều giảng rõ.","Lúc đó chư vị Học sĩ trong cõi tam thiên","ngồi lắng nghe đức Phật tụng giới,","hết lòng kính trọng, hoan hỷ thọ trì\u0001"]],["v",["Đức Phật Thích Ca Mâu Ni giảng xong","về mười vô tận giới pháp trong phẩm","“Tâm Địa Pháp Môn” của đức Phật","Lô Xá Na đã giảng nơi thế giới","Liên Hoa Đài Tạng lúc trước,","nghìn trăm ức đức Thích Ca","cũng đồng giảng như vậy."]],["v",["Từ cung Đại Tự Tại Thiên Vương","đến dưới cây Bồ Đề này,","thuyết pháp cả mười chỗ,","vì tất cả Bồ Tát và vô số đại chúng","thọ trì đọc tụng giải thuyết pháp nghĩa","cũng như vậy.","Nghìn trăm ức thế giới,","Liên Hoa Đài Tạng thế giới,","vi trần thế giới,","chư Phật cũng giảng thuyết như vậy."]],["v",["Tất cả Phật Tâm Tạng,","Địa Tạng, Giới Tạng,","Vô Lượng Hạnh Nguyện Tạng,","Nhân Quả Phật Tánh Thường Trụ Tạng.","Tất cả chư Phật giảng thuyết","vô lượng pháp tạng như thế đã xong\u0001","Hết thảy chúng sanh","trong nghìn trăm ức thế giới","đều thọ trì hoan hỷ phụng hành.","Còn về phần giảng rộng","những hành tướng của tâm địa","thời như trong phẩm","“Phật Hoa Quang Vương Thất Hạnh”","có nói."]]]},{"t":"IX. Kệ Khen Tặng Giới Pháp","b":[["v",["Người trí nhiều Định Huệ","Thọ trì được pháp này","Lúc còn chưa thành Phật","Được hưởng năm điều lợi:","Một là Thập Phương Phật","Thương tưởng hộ trì luôn","Hai là lúc lâm chung","Chánh niệm lòng vui vẻ","Ba là sanh chỗ nào","Cùng Bồ Tát làm bạn","Bốn là những công đức","Giới độ đều thành tựu","Năm, đời này, đời sau","Đủ giới và phước huệ","Đây là các Phật Tử","Người trí khéo nghĩ lường","Kẻ trước tướng chấp ngã (Phàm phu)","Không thể được pháp này","Người trầm không trệ tịch (Tiểu Thừa)","Cũng không gieo giống được.","Muốn nảy mầm Bồ Đề","Trí Huệ soi thế gian","Phải nên quan sát kỹ","Thật tướng của các pháp:","Không sanh cũng không diệt","Không thường lại không đoạn","Chẳng đồng cũng chẳng khác","Chẳng đến cũng chẳng đi.","Trong thể nhất tâm ấy","Siêng tu tập trang nghiêm,","Công hạnh của Bồ Tát","Phải tuần tự học tập.","Nơi học, nơi “Vô học”","Chớ mống tưởng phân biệt","Đấy là “Đệ Nhất Đạo”,","Cũng gọi pháp Đại Thừa","Hết thảy lỗi hý luận","Đều từ đây dứt sạch","Vô thượng trí của Phật","Đều do đây mà thành.","Vì thế nên Phật Tử","Phải phát tâm dõng mãnh","Nghiêm trì giới của Phật","Tròn sạch như Minh Châu.","Chư Bồ Tát quá khứ","Đã từng học giới này,","Hàng vị lai sẽ học,","Người hiện tại đương học.","Đây là đường Phật đi","Là chỗ Phật khen ngợi.","Ta đã giảng giới xong","Phước đức nhiều vô lượng,","Hồi hướng cho chúng sanh","Đồng đến “Nhất Thiết Trí”","Nguyện ai nghe pháp này","Đều được thành Phật đạo"]]]},{"t":"X. Phần Hồi Hướng","b":[["v",["Trên Liên Hoa Đài Tạng","Lược giảng Tâm Địa Pháp Môn này","Truyền lại chư Thế Tôn","Khinh, Trọng giới phân rành","Tất cả được nhờ ân","Nam mô Phạm Võng Giáo Chủ Lô Xá Na"]],["p","Phật Biến Pháp Giới Tam Bảo. (3 lần)"]]},{"t":"Kiết Kinh Kệ","b":[["v",["Trời, A Tu La, Dạ Xoa thảy","Ai đến nghe pháp phải hết lòng","Ủng hộ Phật Pháp cho thường còn","Mọi người siêng tu lời Phật dạy","Bao nhiêu thính giả đến chỗ này","Hoặc ở cõi đất hoặc trên không","Nương theo chánh pháp ngày đêm tu","Xót thương người đời luôn cứu hộ","Cầu cho Thế giới thường an ổn","Phước trí vô biên lợi quần sanh","Tất cả tội nghiệp đều tiêu trừ","Dứt hẳn quả khổ vào viên tịch","Thường dùng giới hương thoa vóc sáng","Luôn gìn định phục mặc che thân","Hoa mầu trí giác khắp trang nghiêm","Khắp xứ, khắp nơi thường an lạc."]],["p","Nam mô Hộ Pháp Chư Tôn Bồ Tát Ma Ha"],["p","Tát. (3 lần)"],["p","(Người tụng giới đứng dậy chắp tay nói: Kính bạch đại chúng, nay tôi là... vưng lịnh tụng giới, vì ba nghiệp biếng trễ, nếu có điều chi sai sót, xin đại chúng bố thí hoan hỷ.)"]]},{"t":"Ma Ha Bát Nhã Ba La Mật Đa Tâm Kinh","b":[["p","Quán tự tại Bồ tát, hành thâm Bát Nhã Ba la mật đa thời, chiếu kiến ngũ uẩn giai không, độ nhất thiết khổ ách."],["p","Xá Lợi Tử! Sắc bất dị không, không bất dị sắc, sắc tức thị không, không tức thị sắc, thọ, tưởng, hành, thức, diệc phục như thị."],["p","Xá Lợi Tử! Thị chư Pháp không tướng, bất sanh, bất diệt, bất cấu, bất tịnh, bất tăng, bất giảm. Thị cố không trung, vô sắc, vô thọ, tưởng, hành, thức, vô nhãn, nhĩ, tỷ, thiệt, thân, ý, vô sắc, thinh, hương, vị, xúc, pháp, vô nhãn giới, nãi chí vô ý thức giới, vô vô minh diệc, vô vô minh tận, nãi chí vô lão tử, diệc vô lão tử tận, vô khổ, tập, diệt, đạo, vô trí diệc vô đắc."],["p","Dĩ vô sở đắc cố, Bồ đề tát đỏa y Bát nhã ba la mật đa cố, tâm vô quái ngại, vô quái ngại cố, vô hữu khủng bố, viễn ly điên đảo mộng tưởng, cứu cánh Niết bàn."],["p","Tam thế chư Phật, y Bát nhã ba la mật đa cố, đắc a nậu đa la tam miệu tam bồ đề."],["p","Cố tri Bát nhã Ba la mật đa, thị đại thần chú, thị đại minh chú, thị vô thượng chú, thị vô đẳng đẳng chú năng trừ nhứt thiết khổ, chơn thiệt bất hư."],["p","Cố thuyết Bát nhã ba la mật đa chú, tức thuyết chú viết:"],["p","Yết đế yết đế, ba la yết đế, ba la tăng yết đế, Bồ đề tát bà ha. (3 lần)"]]},{"t":"Hồi Hướng","b":[["v",["Thính giới công đức thù thắng hạnh","Vô biên thắng phước giai hồi hướng","Phổ nguyện pháp giới chư chúng sanh","Tốc vãng vô lượng quang Phật sát.","Nguyện tiêu tam chướng trừ phiền não","Nguyện đắc trí huệ chơn minh liễu","Phổ nguyện tội chướng tất tiêu trừ","Thế thế thường hành Bồ Tát đạo.","Nguyện sanh Tây phương Tịnh độ trung","Cửu phẩm liên hoa vi phụ mẫu","Hoa khai kiến Phật ngộ vô sanh","Bất thối Bồ Tát vi bạn lữ."]],["v",["Nguyện dĩ thử công đức","Phổ cập ư nhứt thiết","Ngã đẳng dữ chúng sanh","Giai cộng thành Phật đạo."]],["p","Tự quy y Phật, đương nguyện chúng sanh, thể giải đại đạo, phát vô thượng tâm."],["p","Tự quy y Pháp, đương nguyện chúng sanh, thâm nhập Kinh tạng, trí huệ như hải."],["p","Tự quy y Tăng, đương nguyện chúng sanh, thống lý đại chúng, nhứt thiết vô ngại."]]},{"t":"Nguyện","b":[["p","A Di Đà Phật, thường lai hộ trì, linh ngã thiện căn, hiện tiền tăng tấn, bất thất tịnh nhơn. Lâm mạng chung thời, thân tâm chánh niệm, thị thính phân minh, diện phụng Di Đà, dữ chư Thánh chúng, thủ chấp hoa đài, tiếp dẫn ư ngã. Nhất sát na khoảnh, sanh tại Phật tiền, cụ Bồ tát đạo, quảng độ chúng sanh, đồng thành chủng trí."]]},{"t":"Chí Tâm Đảnh Lễ","b":[["p","Nam mô Tây Phương Cực Lạc Thế Giới, Đại Từ Đại Bi A Di Đà Phật."],["p","Nam mô Đại Bi Quan Thế Âm Bồ Tát, Đại Thế Chí Bồ Tát, Thanh Tịnh Đại Hải Chúng Bồ tát."],["p","Nam mô Liên Trì Hải Hội Phật, Bồ Tát, Hiền Thánh Chúng Chư Thượng Thiện Nhơn."]]},{"t":"Phần Chú Thích","b":[["p","(1) Tụng giới trước chư Tăng, hỏi thời gọi “Chư Đại"],["p","Đức”. Nếu trước hàng Sa di Bồ tát hay trước hàng Tại gia Bồ tát, thời đổi lại “Chư Đại Chúng”, hay “Chư Phật Tử”. Dưới đây, trong đoạn tiền phương tiện và đoạn bài tựa cũng vậy."],["p","(2) Theo chánh pháp, một năm 12 tháng chia làm 3"],["p","mùa Xuân, Hạ và Đông. Từ 16 tháng chạp đến 15 tháng 4 là mùa Xuân. Từ 16 tháng 4 đến 15 tháng tám là mùa Hạ. Từ 16 tháng 8 đến 15 tháng chạp là mùa Đông. Nếu ngày tụng giới nhằm mùa Hạ hay mùa Đông thời tụng là “Hạ phần” hay “Đông phần”."],["p","Như ngày 30 tháng chạp tụng giới thời xướng: “Phần mùa Xuân, bốn tháng làm một mùa, nửa tháng đã qua, thiếu một đêm, thừa một đêm, còn ba tháng rưỡi.”"],["p","Rằm tháng giêng thời xướng: “Phần mùa Xuân, bốn tháng làm một mùa, một tháng đã qua, thiếu một đêm, thừa một đêm, còn ba tháng.”"],["p","Cho đến rằm tháng tư thời xướng: “Phần mùa Xuân, bốn tháng làm một mùa, bốn tháng đã qua, thiếu một đêm, còn thừa một đêm.” v.v..."],["p","(3) Hoặc tụng “Một tháng, một tháng rưỡi, hai"],["p","tháng, hai tháng rưỡi, ba tháng, ba tháng rưỡi, bốn tháng”."],["p","(4) Lời xướng đây là tụng giới trong ngày ba mươi"],["p","tháng chạp: Từ 16 đến 30 là đã qua nửa tháng mùa Xuân, nên nói “nửa tháng đã qua”, nhưng đến sáng mùng một mới mãn ngày 30, nên nói “còn thiếu một đêm”, và nói “thừa một đêm” là vì ba tháng rưỡi còn lại của mùa Xuân, còn dư đêm ba mươi vậy."],["p","(5) Hoặc tụng “Còn ba tháng, còn hai tháng rưỡi,"],["p","còn hai tháng, còn một tháng rưỡi, còn một tháng, còn nửa tháng”. Hoặc chỉ tụng “Còn thừa một đêm”, nếu đã qua bốn tháng."],["p","(6) Tiếng Phạn “Ba la đề mộc xoa”, Trung Hoa dịch"],["p","là “Bảo giải thoát”: Giới pháp này bảo đảm sự giải thoát cho người tôn kính thọ trì."],["p","(7) Tháng thiếu, ngày 14 tức là ngày 29 cuối tháng."],["p","Ngày Rằm thời nói ngày thứ 15 “có trăng”, nếu ngày 29 hay 30 thời nói là ngày 14 hay 15 “không trăng”."],["v",["(8) Tiếng Phạn, dịch là Trưởng tịnh (trưởng dưỡng","thiện căn, tịnh trừ nghiệp chướng).","(9) Phẩm “Bồ Tát Tâm Địa” có hai phần:"]],["p","Phần trên: Đức Lô Xá Na Phật giảng về Quả vị của Bồ tát có bốn mươi bậc: Thập Phát Thú, Thập Trưởng Dưỡng, Thập Kim Cương, Thập Địa."],["p","Phần dưới: Đức Thích Ca Mâu Ni Phật kiết giới Bồ tát: 10 điều trọng và 48 điều khinh."],["p","(10) Kinh văn trong phần trên nói: Lúc ấy, đức"],["p","Thích Ca liền đem đại chúng nơi thế giới này về đến nơi Liên Hoa Đài Tạng thế giới, trong cung Bá Vạn Ức Tử Kim Cương Quang Minh, thấy đức Lô Xá Na Phật ngự trên tòa Bá Vạn Ức Liên Hoa chói sáng rực rỡ."],["p","(11) Kinh văn trong phần trên, đức Lô Xá Na phán:"],["p","“Ta đã tu hành tâm địa trong trăm A tăng kỳ kiếp, dùng đó làm nhân, bỏ hẳn phàm phu, thành bậc Vô thượng Chánh đẳng Chánh giác, hiệu là Lô Xá Na, ngự nơi Liên Hoa Đài Tạng thế giới”."],["p","“A tăng kỳ” Phạn ngữ, Trung Hoa dịch là vô số. (12) Kinh văn trong phần trên nói: “Liên Hoa đài ấy"],["p","có nghìn cánh, mỗi cánh là một thế giới, thành một nghìn thế giới. Đức Lô Xá Na phán: “Ta hóa làm một nghìn Thích Ca ngự nơi nghìn thế giới ấy. Về sau cứ mỗi thế giới trên mỗi cánh hoa lại có trăm ức núi Tu Di, trăm ức mặt nhựt, mặt nguyệt, trăm ức Nam Diêm Phù Đề, trăm ức Bồ tát Thích Ca ngồi dưới trăm ức cội Bồ Đề, v.v..."],["p","Trong bộ Hiệp Chú giải: một ức là một nghìn vạn, tức là mười triệu (10,000,000) --- Một Tu Di, một Thái dương hệ là một tiểu thế giới. --- Một nghìn Thái dương hệ là một Tiểu thiên thế giới --- Một nghìn tiểu thiên (1,000,000) là một Trung thiên thế giới. --- Một nghìn Trung thiên thế giới (1,000,000,000) là một Đại thiên thế giới. Đài hoa có nghìn cánh, thành tất cả có một nghìn Đại thiên thế giới, hay là một nghìn tỷ Tiểu thế giới (1,000,000,000,000). --- Mỗi Tiểu thế giới (Một Thái dương hệ), một đức Thích Ca, thành tất cả là một nghìn tỷ Thích Ca, hay là thiên bá ức Thích Ca (nghìn trăm ức)."],["p","(13) Tòa Kim Cương Hoa Quang ở tại cội Bồ Đề nơi"],["p","đức Thích Ca thành đạo."],["p","Diệu Quang Đường là cung của trời Tứ Thiên Vương, từng trời thứ nhất trong sáu cõi trời dục giới."],["p","(14) Thập Trụ: (1) Phát tâm trụ, (2) Trị địa trụ, (3) Tu"],["p","hành trụ, (4) Sanh quý trụ, (5) Phương tiện cụ túc trụ, (6) Chánh tâm trụ, (7) Bất thối trụ, (8) Đồng chơn trụ, (9) Pháp vương tử trụ, (10) Quán đảnh trụ. Thập trụ đây có thể hiệp với Thập Phát Thú."],["p","(15) Thập Hạnh: (1) Hoan hỷ hạnh, (2) Nhiêu ích"],["p","hạnh, (3) Vô sân hận hạnh, (4) Vô tận hạnh, (5) Ly si loạn hạnh, (6) Thiện hiện hạnh, (7) Vô trước hạnh, (8) Tôn trọng hạnh, (9) Thiện pháp hạnh, (10) Chơn thiệt hạnh. Thập Hạnh đây có thể hiệp với Thập Trưởng Dưỡng."],["p","(16) Thập Hồi Hướng: (1) Cứu hộ chúng sanh ly"],["p","chúng sanh tướng hồi hướng, (2) Bất hoại hồi hướng, (3) Đẳng nhất thiết Phật hồi hướng, (4) Chí nhất thiết xứ hồi huớng, (5) Vô tận công đức tạng hồi hướng, (6) Tùy thuận bình đẳng thiện căn hồi hướng, (7) Tùy thuận đẳng quán nhất thiết chúng sanh hồi hướng, (8) Chơn như tướng hồi hướng, (9) Vô phược giải thoát hồi hướng, (10) Pháp giới vô lượng hồi hướng. Thập Hồi Hướng đây có thể hiệp với Thập Kim Cương."],["p","(17) Thập Địa: (1) Hoan hỷ địa, (2) Ly cấu địa, (3) Phát"],["p","quang địa, (4) Diệm huệ địa, (5) Nan thắng địa, (6) Hiện tiền địa, (7) Viễn hành địa, (8) Bất động địa, (9) Thiện huệ địa, (10) Pháp vân địa."],["p","(18) Tịch Diệt là Niết Bàn: Đức Phật dùng Đại Bồ Đề"],["p","trí chứng Đại Niết Bàn lý. Đạo Tràng Tịch Diệt chính là Bồ Đề Đạo Tràng."],["p","(19) Phạm là Đại Phạm Thiên Vương, tức là vua cõi"],["p","trời Tứ Thiền, cũng gọi là Đại Tự Tại Thiên Vương. Nhân vì trong hội thuyết pháp này, đức Phật dùng bửu võng của Đại Phạm Thiên Vương làm tỉ dụ, nên gọi là Kinh Phạm Võng."],["p","Bửu võng là bức mành kết bằng bửu châu treo trước điện Thiên Vương."],["p","(20) Về giới của Bồ Tát có ba phần:"],["p","(a) Nhiếp luật nghi giới (những điều ngăn cấm thân, khẩu, ý, không cho phạm tội lỗi)."],["p","(b) Nhiếp thiện pháp giới (những điều lành, điều tốt mà thân, khẩu, ý phải thực hành)."],["p","(c) Nhiêu ích hữu tình giới (những điều cứu khổ ban vui cho chúng sanh)."],["p","Nhiếp luật nghi giới đưa Bồ Tát đến quả Đoạn Đức (Đại Niết Bàn), chứng Thanh tịnh pháp thân."],["p","Nhiếp thiện pháp giới đưa Bồ Tát đến quả Trí Đức (Đại Bồ Đề), chứng Viên mãn báo thân."],["p","Nhiêu ích hữu tình giới đưa Bồ Tát đến quả Ân Đức (Đại Từ Bi), chứng Ứng hóa thân."],["p","“Kim Cương” thể chất bền chắc trong sạch, dùng dụ cho Đại Niết Bàn, “Quang Minh” chiếu sáng khắp nơi, dùng dụ cho Đại Bồ Đề, “Bửu” có năng lực làm cho người khỏi nghèo khổ, được vui sướng, dùng dụ cho Đại Từ Bi."],["p","Vì những ý nghĩa trên nên dùng danh từ “Quang Minh Kim Cương Bửu Giới” để gọi ba phần giới Bồ Tát."],["p","Và vì ba phần giới Bồ Tát có năng lực đưa hành giả đến Phật quả, nên giới này là chủng tử của Phật tánh, là bổn nguyện của Bồ Tát và của chư Phật. Do đây mà biết rằng nếu không có giới pháp này, chúng sanh không thể thành Bồ Tát, không thể thành Phật được."],["p","(21) Như đoạn trên nói giới pháp này là chủng tử"],["p","của Phật tánh. Tất cả chúng sanh đều có Phật tánh, thành ra giới pháp này là giới phẩm của tất cả chúng sanh."],["p","“Bổn nguyên tự tánh thanh tịnh” là thể tánh thanh tịnh bổn hữu của tất cả chúng sanh, tức Phật tánh."],["p","(22) Người trì giới này sẽ được dứt hẳn tất cả tâm"],["p","bệnh, và chứng chơn thường, chơn lạc, chơn ngã, chơn tịnh của quả Đại Niết Bàn, tỉ dụ như Cam lộ, người uống nó sẽ khỏi bệnh khổ mà được an vui và trường sanh."],["p","(23) Mặt trời, mặt trăng và châu ngọc có những đức"],["p","tính: trừ tối tăm, chói sáng, có lợi ích cho sinh vật."],["p","“Trừ tối”, tức là năng lực phá ác của Nhiếp luật nghi giới."],["p","“Chói sáng”, tức là năng lực thành thiện của Nhiếp thiện pháp giới."],["p","“Lợi ích”, tức là năng lực lợi sanh của Nhiêu ích hữu tình giới."],["p","(24) Chơn thiệt Phật tử."],["p","(25) Sư tăng trong đây chỉ cho Hòa thượng và A xà"],["p","lê. Còn chư Tăng, thời là Tăng bảo trong phẩm vị Tam Bảo (lời giải trong bộ Hiệp Chú)."],["p","Hiếu thuận với cha mẹ thời những điều ác về thế gian dứt, mà những điều lành về thế gian sanh trưởng. Hiếu thuận với Sư tăng, Tam Bảo, thời những điều ác của thế gian và xuất thế gian dứt diệt, những điều lành về thế gian và xuất thế gian phát sanh cho đến viên mãn thành tựu."],["p","Vì ý nghĩa ấy, nên hiếu thuận là cốt tủy của Bồ Tát giới, và là chí đạo."],["p","(26) Các Bồ tát đây là chỉ cho chư Bồ tát trong 40 vị:"],["p","Thập Phát Thú, Thập Trưởng Dưỡng, Thập Kim Cương và Thập Địa."],["p","(27) Mười tám Phạm Thiên là 18 cõi trời ở sắc giới."],["p","Trời Sơ Thiền có 3 cõi: (1) Phạm Chúng thiên, (2) Phạm Phụ thiên, (3) Phạm Vương thiên."],["p","Trời Nhị Thiền có 3 cõi: (4) Thiểu Quang thiên, (5) Vô Lượng Quang thiên, (6) Quang Âm Thiên."],["p","Trời Tam Thiền có 3 cõi: (7) Thiểu Tịnh thiên, (8) Vô Lượng Tịnh thiên, (9) Biến Tịnh thiên."],["p","Trời Tứ Thiền có 9 cõi: (10) Phước Sanh thiên, (11) Phước Ái thiên, (12) Quảng Quả thiên, (13) Vô Tưởng thiên, (14) Vô Phiền thiên, (15) Vô Nhiệt thiên, (16) Thiện Kiến thiên, (17) Thiện Hiện thiên, (18) Sắc Cứu Cánh thiên."],["p","(28) Trong Dục giới có 6 từng trời: (1) Trời Tứ thiên"],["p","vương, (2) Trời Đao lợi, (3) Trời Dạ ma, (4) Trời Đâu suất (đức Di Lặc ngự nơi nội viện), (5) Trời Hóa lạc, (6) Trời Tha hóa (chỗ Ma vương ngự)."],["p","(29) Thời ấy Tây Vực chia ra nhiều nước, và đây là 16"],["p","đại quốc: (1) nước Sử Già, (2) nước Ma Kiệt, (3) nước Ca Thi, (4) nước Câu Tát La, (5) nước Bạt Kỳ, (6) nước Mạt La, (7) nước Chi Đề, (8) nước Bạt Sa, (9) nước Ni Lâu, (10) nước Bàn Xà La, (11) nước A Thấp Ba, (12) nước Bà Ta, (13) nước Tô La, (14) nước Càn Đà La, (15) nước Kiếm Phù Sa, (16) nước A Bàn Đề (theo bộ Hiệp Chú)."],["p","(30) Mười bậc Phát Thú Bồ Tát: (1) Xả tâm, (2) Giới"],["p","tâm, (3) Nhẫn tâm, (4) Tấn tâm, (5) Định tâm, (6) Huệ tâm, (7) Nguyện tâm, (8) Hộ tâm, (9) Hỉ tâm, (10) Đảnh tâm. Có thể hiệp với Thập Trụ Bồ Tát."],["p","Mười bậc Trưởng Dưỡng Bồ Tát: (1) Từ tâm, (2) Bi tâm, (3) Hỉ tâm, (4) Xả tâm, (5) Thí tâm, (6) Hảo ngữ tâm, (7) Ích tâm, (8) Đồng tâm, (9) Định tâm, (10) Huệ tâm. Có thể hiệp với Thập Hạnh Bồ Tát."],["p","Mười bậc Kim Cương Bồ Tát: (1) Tín tâm, (2) Niệm tâm, (3) Hồi hướng tâm, (4) Đạt tâm, (5) Trực tâm, (6) Bất thối tâm, (7) Đại thừa tâm, (8) Vô tụng tâm, (9) Huệ tâm, (10) Bất hoại tâm. Có thể hiệp với Thập Hồi Hướng Bồ Tát."],["p","Mười bậc Thể Tánh Địa Bồ Tát: (1) Thể tánh Bình Đẳng địa, (2) Thể tánh Thiện Huệ địa, (3) Thể tánh Quang Minh địa, (4) Thể tánh Nhĩ Diệm địa, (5) Thể tánh Huệ Chiếu địa, (6) Thể tánh Hoa Quang địa, (7) Thể tánh Mãn Túc địa, (8) Thể tánh Phật Hống địa, (9) Thể tánh Hoa Nghiêm địa, (10) Thể tánh Nhập Pháp Giới địa."],["v",["Có thể hiệp với Thập Địa Bồ Tát.","(31) Huỳnh môn là người không phải nam không","phải nữ (kẻ bộ nắp)."]],["p","Tám bộ quỷ thần: (1) Thiên thần, (2) Long thần, (3) Dạ xoa, (4) Càn thát bà (nhạc thần), (5) A tu la, (6) Ca lâu la (kim xí điểu), (7) Khẩn na la (ca thần), (8) Ma hầu la già (thần rắn)."],["p","Thần Kim cương là vị thần cầm chày kim cương, trong phẩm Phổ Môn gọi là Chấp kim cương thần."],["v",["Kẻ biến hóa, như rồng hóa làm người, v.v...","(32) Phương tiện giết là những phương thế trước"]],["p","khi giết, như bắt, trói, nhốt, đè, chỉ đường cho người rượt, cho người bắt, v.v..."],["p","Khen ngợi sự giết là người ấy không có tâm giết, tự mình đến khuyến khích cho người ấy giết, hay tự tử."],["p","Thấy giết tùy hỷ là thấy người giết, rồi tự tán thành, ưng ý sự giết ấy."],["p","Phàm tội sát sanh do đủ bốn điều. Như tội sát sanh đây, tất cả những tội khác cũng đều như vậy."],["p","(a) “Nhơn giết” là cố tâm muốn giết, điều này là trụ cột của tội."],["p","(b) “Duyên giết” là loài hữu tình (người, thú, v.v...) cùng những khí cụ, nơi chỗ, v.v..."],["p","(c) “Cách thức giết” như đâm, chém, đập, đánh, bắn, nhận nước, thiêu đốt, thắt cổ, đổ thuốc độc, v.v..."],["p","(d) “Nghiệp giết”, khi người hay thú, v.v... tắt thở (chết) thời nghiệp giết thành. Chính nơi thế gian này mà kết tội."],["p","Ba La Di tội, Tàu dịch là Khí tội; khí là vứt bỏ."],["p","Người phạm tội này thời bỏ hẳn ra ngoài phạm vi Phật pháp, không còn phải là Bồ tát, không còn phải là Phật tử, là Thích tử nữa."],["p","Cứ theo cảnh mà luận tội thời có ba hạng: nơi cha mẹ, Hòa thượng, A xà lê, Phật và Thánh nhân mà giết thời phạm “tội nghịch”, cũng gọi là “vô gián tội”, cũng gọi là giá tội (giá là ngăn chướng, trọn đời quyết không được thọ giới lại)."],["p","Nơi loài người và tất cả loài khác, những ai có thể nhận hiểu lời nói của Giới sư mà giết thời phạm tội “Ba la di”, mất giới. Người phạm tội này phải sám hối thấy hảo tướng mới được thọ giới lại."],["p","Nơi loài súc sanh, v.v... không hiểu lời nói của giới sư mà giết thì phạm tội trọng, không mất giới. Đối thú sám hối thì thanh tịnh. Ngoài ra còn theo tâm mà luận tội nặng nhẹ, v.v..."],["p","(33) Vật sở hữu của kẻ khác, có tâm gian lén lấy gọi"],["p","là trộm, đoạt lấy gọi là cướp, cùng dối lấy, gạt lấy, gian lận mà lấy, v.v... đều thuộc về trộm cướp cả."],["p","Lấy năm tiền hay nhiều hơn năm tiền (đồ vật thì cứ tính giá mà định) phạm Ba la di, mất giới."],["p","Lấy dưới năm tiền, phạm trọng, không mất giới."],["p","(34) Phật tử tại gia thì trừ vợ chồng chính thức;"],["p","Phật tử xuất gia thời với tất cả nam nữ, nếu hành dâm, phạm Ba la di, mất giới."],["p","Phật tử tại gia, ngày thọ Bát quan trai cũng đồng như người xuất gia."],["p","Phật tử tại gia, nơi vợ chồng chánh thức mà hành dâm trái thời, trái nơi thì phạm tội khinh, phải đối thú sám hối."],["v",["Trái thời là ban ngày, ngày lễ Phật, Bồ tát, ngày trai.","Trái chỗ là trừ năm căn, nữ căn.","Trái nơi là chỗ không phải phòng ngủ riêng của vợ chồng."]],["p","Phi đạo: đối với người nữ, đạo tức là miệng, nữ căn và hậu môn, còn đối với người nam, đạo tức là miệng và hậu môn. Phi đạo hành dâm, nghĩa là hành dâm ở những chỗ khác trên thân thể, ngoài ba chỗ này."],["p","(35) Khi nói vọng mà người khác nhận hiểu lời nói"],["p","ấy thời thành tội. Thân vọng ngữ là ra dấu, lắc đầu, gật đầu, đưa tay, v.v... Tâm vọng ngữ như khi Tăng hỏi, tự biết mình có tội mà vẫn yên lặng, v.v... Vọng ngữ cho người khác nhận lầm mình là bực siêu phàm, đắc thiền, đắc định, chứng Thánh, v.v... thời phạm Ba la di, mất giới."],["p","Những vọng ngữ khác thuộc tội khinh, phải đối thú sám hối."],["v",["(36) Về Bồ tát giới lấy tích cực lợi tha làm chủ, nên","bán rượu phạm tội trọng, còn tự uống rượu phạm tội khinh.","(37) Theo bộ Hiệp Chú, trong mười giới trọng đây,"]],["p","nếu phạm sáu điều sau (từ Bán rượu đến Hủy báng) thì phạm trọng, không mất giới, phải đối thú sám hối, vì là giá giới."],["p","Nhưng nếu không hổ thẹn chừa bỏ, cứ để tâm tương tục thì cũng mất giới."],["p","(38) Đối với mười giới trọng trên, nên 48 điều này"],["p","gọi là giới khinh, cũng gọi là “đọa” (theo ý của Thanh văn giới, vì nếu phạm mà không như pháp sám hối, thế lực của tội có thể làm cho người phạm phải sa đọa.)"],["p","(39) Ngũ tân là năm loại rau tanh nồng. Hưng cừ"],["p","chưa biết là rau gì, các bộ sớ Tàu cho rằng phương này (xứ Tàu) không có. Phàm thứ nào có tánh chất tanh nồng và hình thức tương tợ đều thuộc về các loại này, đều không ăn được, không được dùng gia vị. Như loại hành, thời hành tây, hành tàu, v.v... cũng đều cấm, chớ chẳng phải chỉ cấm hành ta thôi."],["p","Người ăn ngũ tân có các điều tổn: ăn sống thêm lòng nóng giận, ăn chín thêm lòng dâm dục, miệng và mồ hôi tanh, các thiên thần xa tránh, các ác quỷ ưa gần, tụng kinh trì chú không linh, không phước..."],["p","(40) Tám Phước Điền: (1) Phật, (2) Thánh nhơn, (3)"],["p","chư Tăng, (4) Hòa thượng, (5) A xà lê, (6) cha, (7) mẹ, (8) người bệnh."],["p","(41) Người bán quan tài, bán đồ đụng thây chết, v.v..."],["p","ắt muốn bán được chạy, được nhiều, không khỏi có quan niệm trông cho nhiều người chết nên thành tội. Trái lại, nếu bố thí quan tài, v.v... thời đưọc phước rất lớn."],["p","(42) Từ tháng tư đến tháng chín, giống sanh vật nhỏ"],["p","như kiến, trùng, v.v... sanh sản rất nhiều, nên không cho thiêu đốt cỏ cây. Trong đây cháy lan đến của người khác trong trường hợp tình cờ vô ý nên thuộc tội khinh. Nếu cố ý thời thuộc tội trọng thứ hai. Cố ý cho chết sanh vật thời thuộc tội trọng thứ nhứt."],["p","(43) Đem giáo pháp Tiểu thừa, v.v... dạy cho người"],["p","với tâm ác, tâm giận đó là muốn hại người cho mất lợi ích về Đại thừa, nên phạm tội. Nếu vì theo tiểu cơ mà truyền tiểu giáo thì không phạm."],["p","(44) Trong giới này, nương quyền cậy thế bức người"],["p","lấy của, v.v... chỉ trong phạm vi thâu thuế nặng, cho vay nặng lời, tiền đất tiền nhà quá cao, v.v..."],["p","Nếu thật bức người mà sang đoạt thì thuộc tội trọng thứ hai."],["p","(45) Tất cả các kinh của đức Phật thuyết giáo, chia"],["p","ra từng loại thì có 12 phần:"],["v",["1. “Trường hàng” (văn xuôi).","2. “Trùng tụng” (văn vần lặp lại những điều đã"]],["v",["giảng).","3. “Cô khởi” (văn vần đi riêng).","4. “Nhân duyên” (gợi Phật thuyết pháp, cũng"]],["v",["gọi là Duyên khởi).","5. “Bổn sanh” (những đời trước của Phật, của"]],["v",["Bồ tát).","6. “Bổn sự” (những việc trong đời quá khứ của"]],["v",["Phật, Bồ tát).","7. “Vị tằng hữu” (sự hay lý nghĩa làm chúng"]],["v",["ngạc nhiên vì thuở giờ chưa từng có).","8. “Tỉ dụ” (mượn dụ để chỉ Pháp).","9. “Luận nghị” (biện luận chánh nghĩa).","10. “Tự thuyết” (không ai thưa thỉnh, Phật tự"]],["v",["giảng nói.","11. “Phương quảng” (giáo lý Đại thừa).","12. “Thọ ký” (Phật thọ ký cho chư Bồ tát, hay đệ"]],["p","tử bao giờ thành Phật, hiệu gì, ở đâu, v.v...)"],["p","Trong 12 phần, 3 phần Trường hàng, Trùng tụng và Cô khởi là thể tài của kinh văn, ngoài ra chín phần"],["p","kia là những điều, những sự trong kinh văn mà phân loại ra."],["p","46. Đây là tội lưỡng thiệt do thấy người tinh tấn tu"],["p","hành mà sanh lòng tật đố. Trong đây kể một hạnh dâng hương để tỉ dụ cho bao nhiêu hạnh Bồ Tát khác."],["v",["47. Tội không cứu vớt chúng sanh có bốn duyên","thành tội:","a) chúng sanh bị khổ,","b) nhận biết là chúng sanh bị khổ,","c) không có từ tâm,","d) ngồi nhìn không cứu vớt."]],["p","Nếu vì không đủ sức để cứu, thời phải niệm Phật chú nguyện cho nó. Đó là không cứu được xác thân nó, thời cứu huệ mạng nó."],["p","48. Câu “Giết sanh mạng để báo thù sanh mạng, đó"],["p","là việc không thuận với hiếu đạo”, có hai ý:"],["p","a) Như cha mình bị người giết, đó hoặc là do túc nghiệp vay trả nhau, nếu mình giết người để báo thù cho cha, thời túc nghiệp của cha không dứt mà gây thêm oan trái cho cha; hoặc không phải do túc nghiệp, thời cũng kết thêm oan trái cho cha. Thành ra sự báo thù của mình, không lợi ích cho người cha đã bị giết, mà còn làm cho người cha thêm khổ ở tương lai, nên gọi là không thuận với hiếu đạo."],["p","b) Phóng xa tầm đạo nhãn, nhưng trong giới phóng sanh trên, đức Phật nhấn mạnh rằng:"],["p","Tất cả nam nữ đều là cha mẹ của ta trong nhiều đời, vì ta đã có vô lượng thân vê thuở quá khứ. Giết người để báo thù cho cha, chính là vì báo thù cho cha đời này mà đi giết cha ở đời trước, thế cũng là không thuận với hiếu đạo."],["p","Trong giới này căn cứ nơi phạm vi cố báo thù mà kết thêm tội khinh, còn giết sanh mạng thời tự thuộc về giới trọng thứ nhứt."],["p","49. Thọ giới này có ba phẩm đắc giới:"],["p","a) Đối trước Phật cùng Bồ tát mà thọ giới thời thuộc thượng phẩm đắc giới."],["p","b) Thọ với Bồ Tát Giới Pháp Sư thời thuộc trung phẩm đắc giới."],["p","c) Đối trước tượng Phật, tượng Bồ Tát mà tự nguyện thọ thời thuộc hạ phẩm đắc giới."],["p","Trong phần tự nguyện thọ giới này phải đủ hai điều kiện mới đắc giới: (1) Trong nghìn dặm không có Pháp Sư truyền giới, (2) Phải thấy hảo tướng. Nếu có Pháp Sư có thể truyền giới mà không đến xin thọ, lại tự nguyện thọ giới, thời dầu có thấy hảo tướng cũng không đắc giới, vì có tâm khinh mạn vậy."],["p","50. Đây là giới cấm bỏ giáo lý Đại thừa đi học tiểu"],["p","giáo cùng sách ngoại đạo. Bỏ bảy báu có hai ý:"],["p","(a) Giáo lý Đại thừa như châu báu, vàng ngọc, tiểu giáo và sách ngoại đạo như đá, đất. Theo học tiểu giáo, v.v... đó là vất bỏ châu báu Đại thừa vậy."],["p","(b) Không tiếc châu báu, không sợ tổn phí mà đi học tiểu giáo, v.v... đó là tỏ ra quá ham thích, quá chuộng."],["p","51. Tài vật của Tam Bảo, người có phận sự quản lý,"],["p","khi muốn chi tiêu phải đúng luật đúng pháp, không được theo ý riêng. Nếu tự ý riêng, chi tiêu không đúng luật đúng pháp, thì phạm tội."],["p","Trong đây vì chi tiêu sái phép nên thuộc tội khinh, còn nếu tự lấy tiêu riêng, dùng riêng, thời thuộc tội trọng thứ hai."],["p","52. Nơi lợi dưỡng nếu khách Tăng có phần, mà chủ"],["v",["Tăng không cho cùng hưởng, thời trái với điều:","Lợi hòa đồng quân”, nên phạm tội."]],["p","53. Đây là cố ý tìm cách cho thí chủ đem cúng"],["p","riêng cho mình nên phạm tội khinh. Nếu đã thuộc về chư Tăng, Tam Bảo, mà đi dành riêng về phần mình, thời thuộc về tội trọng thứ hai."],["p","54. Phàm là Bồ Tát, hay Phật tử phải có tâm từ bi"],["p","bình đẳng, nếu thỉnh riêng, thời trái với đức bình đẳng nên phạm tội."],["p","Trong đây thỉnh riêng năm trăm La Hán Bồ Tát tăng, đức Phật cho rằng không bằng theo thứ tự mà thỉnh một vị Tăng phàm phu, là vì nơi sự cúng dường bố thí, phước đức nhiều hay ít, chẳng phải chỉ do nới cảnh (người thọ), nơi vật (của tiền)."],["p","55. Cấm đến cả vì tài lợi mà nấu ăn, xay giã, nghề"],["p","nghiệp, v.v... thuộc riêng về phần Bồ tát xuất gia. Còn Bồ tát tại gia tự có nghề nghiệp chơn chánh, lợi mình lợi người. Nhưng không được vì ác tâm mà làm, cũng không được ham tài lợi mà làm, vì bổn phận Phật tử phải xa danh lợi."],["p","Sâu cổ, là loài sâu độc, phẩn nó có thể giết chết người."],["p","56. Trong những ngày trai mà đi phạm giới tạo tội,"],["p","nên kết thêm tội khinh, còn sự phạm giới thời cứ phạm giới nào luận tội về giới ấy."],["p","Sáu ngày trai trong mỗi tháng: --- Mồng tám, mười bốn, rằm, hai mươi ba, hai mươi chín, ba mươi (tháng thiếu thời hai mươi tám, hai mươi chín)."],["p","Ba tháng trường trai mỗi năm: tháng giêng, tháng năm và tháng chín (tục ta thời là tháng giêng, tháng bảy và tháng mười)."],["p","Câu “làm quản lý cho người bạch y”, là nói người xuất gia lại đi gánh vác công việc thế tục giùm cho người tại gia. Chữ “trai” trong luật của Phật là nói “không ăn phi thời” (từ mặt trời chính về hướng tây, cho đến sáng sớm ngày mai là phi thời, không phải giờ ăn). Vì thế nên người tu tại gia trong các ngày trai và những tháng trai nên thọ Bát quan trai."],["v",["57. Nương thế lực lấy của người, đây là trên tội","trọng thứ hai mà kết thêm tội khinh về phần lấn hiếp vậy.","Chứa cất cân non, giạ thiếu phạm tội khinh."]],["p","Nếu dùng cân non, giạ thiếu mà lường gian của người thời thuộc về tội trọng thứ hai, cứ theo giá đồ vật về phần gian lận mà định tội."],["p","Mèo, chồn, chó, v.v... là những thứ săn thịt nên cấm nuôi, nếu chó chỉ để giữ nhà thì không phạm."],["p","Heo chỉ để ăn thịt, hay bán thịt nên cấm nuôi, nếu mua, thuộc phóng sanh mà nuôi thời không phạm."],["p","Trong giới này ở nơi sự nuôi chứa mà kết tội khinh. Còn xúi mèo, chồn, chó, v.v... săn thịt, bắt chuột, v.v... thời người xúi sai phạm tội trọng thứ nhất, nếu mèo, chồn, chó theo lịnh giết chết con thịt."],["p","58. Phật tử lấy từ bi làm chủ, lấy hòa thuận làm"],["p","tông, đâu nên an lòng nhìn xem người đánh nhau, chiến nhau, dầu là võ sĩ đấu võ, cho đến đá gà, đá cá, đá dế, v.v... cũng không được xem (nên chú ý hai chữ “Ác tâm”)."],["p","Đây là điều cấm tà giác tà quán. Trong văn cấm năm điều: (1) xem đấu chiến, (2) mua vui, (3) chơi bời, (4) bói quẻ, (5) làm sứ mạng cho giặc cướp. Năm điều này là những duyên chướng đạo giải thoát, làm tăng thêm phóng vật loạn tâm."],["p","Trong Địa Trì Giới Bổn có nói: “Nếu Bồ Tát lười biếng trễ nải, thích ngủ nghỉ, nếu là không phải giờ, hay thái quá thời phạm tội nhiễm ô (Khinh cấu). Trừ khi có nhơn duyên, như bệnh, yếu, quá mệt nhọc, v.v..."],["p","59. Nhị thừa là Tiểu thừa, cũng gọi là Thanh văn"],["p","thừa, A la hán là tột đích, và Trung thừa, tức là Duyên giác thừa, Bích chi phật là đạo quả cuối cùng."],["p","Đại thừa là con đường duy nhất của Phật quả."],["p","Là Phật tử phải nhắm quả Phật mà tiến, nếu xu hướng theo Nhị thừa, thời là sái nẻo, đâu còn phải thật là Phật tử, nên phạm tội."],["p","60. Hai điều giới thứ 35 cùng 36 đây rất chí thiết"],["p","cho hàng Phật tử trên con đường hành đạo. Là Phật tử không thể thiếu."],["p","Trong điều giới 36, có thể gom lại thành 5 điều nguyện:"],["p","a) Nguyện lìa hẳn dâm dục."],["p","b) Nguyện giữ giới thanh tịnh để xứng đáng thọ tứ sự cúng dường."],["p","c) Nguyện giữ giới thanh tịnh để xứng đáng thọ sự cung kính của người."],["p","d) Nguyện trừ tâm nhiễm ô đối với ngũ trần."],["p","e) Nguyện tất cả chúng sanh đều thành Phật."],["p","Toàn cả năm điều chuyên thuộc Bồ tát xuất gia, nếu là Bồ tát tại gia, thời nơi điều (a) là lìa tà dâm, còn điều (b) là sự cung cấp của xã hội, điều (c) thời là danh dự cá nhân."],["p","61. Đầu đà có nghĩa là phủi sạch trần cấu của thân"],["p","tâm. Trong mười tám món, nhành dương dùng nhăn cho tưa ra để chà răng vì thời ấy không dùng bàn chải. Nước tro dùng như xà bông bây giờ. Ba y: y năm điều, bảy điểu, và đại y (chín điều xấp lên cho đến hai mươi lăm điều). Bình dùng đựng nước. Bát (Bát đa la) dùng đựng cơm và đồ ăn. Lư hương để dâng hương cúng Phật."],["p","Đãy lược nước dùng hộ mạng cho sanh linh."],["p","Con dao để cạo râu tóc, cắt móng tay. Cái nhíp để nhổ lông mũi."],["p","Ba y là y phước điền, đức Phật chế riêng cho Tỳ kheo và Tỳ kheo ni mặc, người chưa thọ giới không nên lạm dụng. Nếu là Thức xoa, Sa di ni thời tự có mạn y, còn hàng tại gia thời chỉ mặc y phục hoại sắc."],["p","Những xứ, những nơi hiểm nạn có nhiều sự cảnh hại thân, chướng đạo, nên cấm đển ở."],["p","Trong Giới Kinh (Đại Luật) lại còn cấm những nơi nhiều kiến, nhiều muỗi."],["p","62. Trong Phật pháp thời trọng đức hạnh, nên y cứ"],["p","nơi ngày thọ giới trước sau mà phân ngôi thứ, chớ không theo tuổi đời, cũng không theo tước vị."],["p","Nếu khi tụng giới có đủ hạng Phật tử, thời nên phân riêng từng đoàn thể mà ngồi; người xuất gia ngồi theo nhóm xuất gia; người tại gia ngồi theo nhóm tại gia."],["p","Trong hàng tại gia nếu có ngại, thời nên chia ra nhiều nhóm có quan tước, cùng nhóm bình dân. Rồi từ mỗi nhóm cứ y theo giới đức mà phân ngôi thứ."],["p","Những người đồng thọ một đàn giới thời cứ theo tên hiệu đứng"],["p","63. Là Phật tử phải nhận chơn những tai nạn, họa"],["p","phước và sự lợi ích. Họa hay phước là do nghiệp ác hay thiện chiêu cảm. Nghiệp từ nơi tâm mà phát khởi. Kinh luật Đại thừa có năng lực chuyển tâm ô trược thành thanh tịnh, chuyển tâm ác thành tâm thiện, chuyển tâm si mê thành tâm giác ngộ. Đọc tụng giảng thuyết kinh luật Đại thừa là một thiện nghiệp cao quý."],["p","Vì thế nên có thể làm cho người chết, vong linh được siêu sanh, ngưòi gặp tai nạn được qua khỏi. Có thể ngừa những sự không may và đem hạnh phúc đến."],["p","Phật tử bao giờ cũng phải có tín tâm sâu mạnh nơi năng lực của giáo pháp Đại thừa, bao giờ cũng lấy sự giải nguy, cứu khổ làm phận sự, nên bổn phận của Phật tử phải giảng kinh luật Đại thừa trong những trường hợp có tai biến xảy đến cho người hay cho mình."],["p","64. Trong nghi Giới Đàn: Giới sư dạy cho người cầu"],["p","giới Bồ Tát thỉnh Thích Ca Mâu Ni Phật làm Hòa Thượng, thỉnh đức Văn Thù và đức Di Lặc làm A Xà Lê. Sám hối có ba cách:"],["p","a) Tác pháp sám hối: người có tội đối truớc chư Tăng, hoặc hai mươi vị, bốn vị, ba vị, một vị mà phát lồ sám hối, tùy theo tội lớn nhỏ;"],["p","b) Thủ tướng sám hối: tức là sám hối cho được thấy hảo tướng;"],["p","c) Vô sanh sám hối: quán chơn lý thật tướng, chứng ngộ vô sanh thời tội diệt."],["p","Vô sanh sám hối có thể diệt tất cả tội, dầu là tội thất nghịch; Thủ tướng sám có thể diệt tội thập trọng và tất cả tội khinh; Tác pháp sám hối chỉ trừ được tội khinh. Đối thú sám hối tức là Tác pháp sám hối."],["p","Đệ nhất nghĩa đế là thể tánh của giới pháp, là chánh nhơn của tâm địa, là lý cảnh của chơn trí. Tập chủng tánh, trưởng dưỡng tánh, là do nghiên cứu tu tập không quán lần lần tăng trưởng, tức là Thập phát thu tâm."],["p","Tánh chủng tánh, bất khả hoại tánh là do phân biệt giả tánh (giả quán) mà tục đế kiến lập nên không thể hoại, tức là Thập trưởng dưỡng tâm."],["p","Đạo chủng tánh là trung đạo Thập kim cương tâm. Chánh pháp tánh là chứng nhập chánh vị (chơn như) tức là Thập địa, Đẳng giác và Diệu giác."],["p","Những quán hạnh đa, thiểu, xuất, nhập trong các pháp đó: nghĩa là Phát thu tâm thời từ giả nhập không quán; Trưởng dưỡng tâm thời xuất không quán nhập giả quán; Kim cương tâm thời xuất không giả nhập trung đạo quán; Thập địa thời nhập Thánh. Tập chủng tánh thời không quán thiểu (ít); Trưởng dưỡng tánh thời không quán đa (nhiều); Tánh chủng tánh thời giả quán thiểu; Bất khả hoại tánh thời giả quán đa; Đạo chủng tánh thời trung quán thiểu; Chánh pháp tánh thời trung quán đa. Lai tam quán (không giả trung) theo tuần tự mà tu thời là thiểu, còn tu tập cả trong nhất tâm thời là đa."],["p","Mười chi thiền. Sơ thiền có 5 chi: 1) giác, 2) quán, 3) hỉ, 4) lạc, 5) nhứt tâm."],["p","Nhị thiền có 4 chi: 1) Hỉ, 2) lạc, 3) nhất tâm, 4) nội tịnh."],["p","Tam thiền có 5 chi: 1) lạc, 2) nhứt tâm, 3) xả, 4) niệm, 5) huệ."],["p","Tứ thiền có 4 chi: 1) nhứt tâm, 2) xả, 3) niệm, 4) bất khổ bất lạc."],["p","Nói tổng quát thời có mười chi thiền: 1) giác, 2) quán, 3) hỉ, 4) lạc, 5) nhứt tâm, 6) nội tịnh, 7) xả, 8) niệm, 9) huệ, 10) bất khổ bất lạc."],["p","Trong văn, không hiểu giới khinh, trọng, thị, phi, thời mù mờ nơi giới tướng, không thể quyết nghi xuất tội."],["p","Không hiểu đệ nhất nghĩa đế, thời mù mờ nơi giới lý (thể tánh của tất cả giới), không thể phát khởi chơn thiệt tín giải."],["p","Không hiểu tập chủng tánh, v.v... thời mù mờ nơi định cộng giới, không thể tu chứng quả vị."],["p","Không thông hiểu như thế mà lại làm tuồng là thông hiểu để được cúng dường nhiều, đệ tử đông, thành tội khi dối."],["p","65. Trừ Quốc vương, vì Phật đem chánh pháp phó"],["p","chúc cho Quốc vương hộ trì."],["p","Nếu đem giới này giảng cho người chưa thọ thời có hai điều bất lợi:"],["p","a) Hạng căn khí tiểu thừa và ngoại đạo, người ác sẽ sanh niệm bất kính;"],["p","b) Về sau lúc thọ giới tâm trân trọng kém."],["p","Trong điều giới 39, bảo phải giảng thuyết kinh luật Đại thừa cho tất cả chúng sanh, bất luận lúc nào và chỗ nào (luật Đại thừa là Bồ Tát giới)."],["p","Trong điều giới thứ 42 này lại không cho giảng thuyết giới Bồ Tát trước những người chưa thọ giới Bồ Tát, vậy có chỗ nào mâu thuẫn chăng?"],["p","Xét ra nới điều giới 39 ở trong phạm vi giải nạn cứu khổ nên bảo giảng thuyết với tất cả. Còn trong điều giới 42 này thời vì ngừa tội lỗi nên cấm giảng cho người chưa thọ giới. Cứ theo đây mà suy cứu thời Bồ Tát giới chỉ cấm người chưa thọ dự nghe trong thời bố tát mỗi nửa thánh, nên khi bố tát, trước khi tụng giới phải bảo người chưa thọ ra ngoài, còn những lúc khác thì không kể. Không đồng như tiểu thừa giới (tỳ kheo, tỳ kheo ni giới) thì cấm hẳn, vì người chưa thọ cụ túc giới mà dự biết danh nghĩa những giới điều của tỳ kheo hay của tỳ kheo ni, thời thành chướng nạn, đời này không được thọ cụ túc giới. Ý trên đây là thể theo bộ Hiệp Chú."],["p","66. Người thọ giới mà có tâm hộ trì thời từ người"],["p","cho đến thiên thần đều kính trọng, còn mống tâm phá giới thời tất cả đều khinh khi. Đây là từ lúc mống tâm phá giới mà kết tội khinh, vì người đã thọ giới phải có bổn phận hộ trì, mống tâm muốn phá là thiếu bổn phận nên thành lỗi. Nếu đã phá giới thời tùy giới mà luận tội."],["p","67. Theo văn, cúng dường kinh luật có 5 điều: 1)"],["p","thọ trì, 2) đọc, 3) tụng (thuộc lòng), 4) biên chép, 5) hương hoa châu báu vàng bạc để đựng, để trang nghiêm."],["p","Lột da, chích máu, chẻ xương là cử trọng để lệ cho khinh. Như tiền thân của đức Bổn Sư đã thật hành để cầu Pháp."],["p","68. Thuyết pháp cho loài súc sanh cũng có lợi ích,"],["p","vì ảnh hưởng của tâm lực (tư tưởng), nên trong văn có câu: “Tâm nghĩ miệng nói (nên chú ý hai chữ “tâm nghĩ”), và hoặc giả, có loài nhận được lời, hay hiểu ý của người."],["p","Lưu Thủy trưởng giả với mười nghìn con cá mắc cạn, tôn giả Xá Lợi Phất với con chó bị chặt chưn, v.v... là những bằng cớ cho vấn đề này."],["p","69. Bốn bộ đệ tử: 1) cư sĩ, 2) vợ cư sĩ, 3) đồng nam,"],["p","4) đồng nữ."],["p","Không cho xuất gia thời là đoạn Tăng bảo; không cho tạo hình tượng, tháp thời là đoạn Phật bảo; không cho tạo kinh luật thời là đoạn Pháp bảo."],["p","70. Người xuất gia được giảng thuyết Bồ Tát giới"],["p","cho Quốc vương và các quan đã thọ giới, nhưng không được ở trước quan chức trị phạt phi pháp. Nếu đệ tử có lỗi chỉ nên theo luật mà trị phạt, không nên gông, trói như ngục tù, làm thương tổn thể thống người xuất gia."],["p","Lại lấy sự ấp yêu con một của mẹ hiền và sự thờ kính cha mẹ của con thảo để tỷ dụ lòng của Phật tử hết sức kính mến giới luật."],["v",["71. Trì giới này đại lược có ba điều lợi ích:","1) Lìa khổ (đời đời không bị đọa ác đạo, bát nạn).","2) Được vui (thường sanh trong người trời hưởng phước).","3) Được gặp Phật gần Phật.","72. Ba nghìn học sĩ (Hán: tam thiên học sĩ): là"]],["p","những hàng đồng thọ trì Bồ Tát giới trong tam thiên đại thiên thế giới."],["p","73. Tâm tạng chỉ cho ba mươi tâm (Thập phát thu"],["p","tâm, Thập trưởng dưỡng tâm, Thập kim cương tâm). Địa tạng chỉ cho Thập địa. Giới tạng chỉ cho 10 giới trọng và 48 giới khinh. Vô lượng hạnh nguyện tạng là lục độ vạn hạnh của Đại thừa. Nhơn quả Phật tánh thường trụ tạng:"],["p","Phật tánh tức là thật tướng, là nhơn của Đại thừa mà cũng là quả của Đại thừa."],["v",["74. Tức là phàm phu.","75. Tức là tiểu thừa","76. Trong đoạn kệ văn này vạch rõ sự lợi ích lớn"]],["p","của người trí giữ giới khi chưa thành Phật được hưởng 5 điều:"],["p","a) Được tất cả chư Phật trong mười phương thương tưởng hộ niệm luôn."],["p","b) Vì giữ giới nên không tội không lỗi, lúc lâm chung tâm không loạn động, chánh niệm hiện tiền, sẽ được báo thân tốt hơn nên lòng an vui thơi thới."],["p","c) Thọ trì giới Bồ Tát là đi trên đường của Phật, là bạn đồng học của Bồ Tát, nên thọ sanh nơi nào cũng được gần chư Bồ Tát cả."],["p","d) Giới là nền tảng của tất cả công đức, thọ trì giới pháp thời có thể thành tựu nhiều công đức lớn, và lần được viên mãn Giới Ba la mật (giới độ)."],["p","e) Do trì giới nên xuất sanh định huệ, đạt tánh thể của giới, y tánh khởi tu nên phước được viên mãn, toàn tu tại tánh nên huệ được viên mãn. Phước và Huệ đều viên mãn là bực Vô thượng Chánh giác. Trong văn nói “Đời này và đời sau đủ giới và phước tuệ” là từ vị quán hạnh nhẫn đến đủ giới (đạt giới tánh) đủ phước huệ (phước trí viên mãn) chứng vị cứu cánh (Phật quả)."],["p","Đạt được thật tướng chơn tánh nên trong nhứt tâm đủ cả vạn hạnh. Toàn tánh khởi tu là vô học mà luôn học. Toàn tu tại tánh là luôn học mà vẫn vô học. Vì thế nên văn nói: “Nơi học nơi vô học, chớ mống tưởng phân biệt”. Vì phân biệt tức là sai với tánh thể thật tướng vậy."],["p","Trì giới như minh châu, có ba nghĩa:"],["p","a) Giữ giới tròn vẹn không sai phạm như viên minh châu tròn trịa không tỳ vết."],["p","b) Giữ giới thanh tịnh không ô nhiễm như viên minh châu trong suốt."],["p","c) Giữ giới với tâm trí sáng suốt, nhờ sự trì phát huệ đạt tánh thể thành lý trì, như viên minh châu chói sáng."],["p","Nhứt thế trí, nói đủ là “Nhứt thế trí trí” hay “Nhứt thế chủng trí”, là trí huệ vô thượng của Phật."]]}]};
